'use strict';
const $=s=>document.querySelector(s),assets='assets/';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(n,a)=>`<img src="assets/${n}" alt="${a}">`;
const KEY='courtside-concept-v2';
const dates=['Jan 10–16','Jan 17–23','Jan 24–30','Jan 31–Feb 6','Feb 7–13','Feb 14–20','Feb 21–27'];
const fresh=()=>({version:2,draft:{path:'group',step:1,weeks:[],players:'Not sure yet',partners:'Not sure yet',tennis:'Help us decide',party:'Solo',level:'Not sure yet',name:'',email:'',notes:''},group:null,active:'alex',requests:[],match:null,applications:[],hostApproved:false,hostPaid:false,suppliers:[{id:'hotel',title:'La Finca accommodation',detail:'Room mix + availability',status:'To request'},{id:'club',title:'Club de Tenis Almoradí',detail:'Courts + coaching schedule',status:'To request'},{id:'transport',title:'Ground transportation',detail:'Airport + club transfers',status:'To request'},{id:'support',title:'Trip support',detail:'Local lead + remote cover',status:'To request'}],tasks:[],activity:[],hostIdeas:[],hostTrip:'spain',hostStage:'before'});
let state;try{state=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}if(!state||state.version!==2)state=fresh();
let tripPhase='Before travel';let tab='Overview',day=2,scheduleMode='personal',teamTab='Attention',hostTab='Overview',requestFilter='All',lastFocus=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable. This walkthrough will last for this visit only.')}}
function route(){return location.hash.replace(/^#\//,'').split('?')[0]||''}
function go(p){if(route()===p){render();window.scrollTo(0,0)}else location.hash='/'+p}
function toast(s){const t=document.createElement('div');t.className='toast';t.textContent=s;$('#live').textContent=s;document.body.append(t);setTimeout(()=>t.remove(),4200)}
function stamp(){return new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}
function log(s){state.activity.unshift({text:s,time:stamp()});state.activity=state.activity.slice(0,30)}
function uid(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6)}
function badge(s,type=''){return `<span class="badge ${type}">${esc(s)}</span>`}
function link(p,t,cls='btn'){return `<a class="${cls}" href="#/${p}">${t}</a>`}
function select(name,values,val,extra=''){return `<select name="${name}" ${extra}>${values.map(v=>`<option value="${esc(v)}" ${v===val?'selected':''}>${esc(v)}</option>`).join('')}</select>`}
function field(name,label,value='',type='text',required=false,placeholder=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}"></label>`}
function note(t='Interactive concept. Sample data stays in this browser. No messages, payments or bookings are sent.'){return `<div class="demo-note">${t}</div>`}
function progress(stage){const stages=['Inquiry','Planning','Proposal','Confirmed'];return `<div class="stepsbar" aria-label="Group planning stage">${stages.map(s=>`<span class="${s===stage?'current':''}">${s}</span>`).join('<i aria-hidden="true">›</i>')}</div>`}
function tripmini(){return `<div class="tripbanner">${img('coast.jpg','Katie and Eva on the Costa Blanca')}<div><div class="eyebrow">WITH KATIE + EVA</div><h3>The Spanish Offseason</h3><p>Six nights · Costa Blanca, Spain<br>${esc(groupDate())}, 2027</p></div></div>`}
function aside(){return `<aside class="flow-aside card"><div class="card-image">${img('coast.jpg','Katie and Eva together in Spain')}</div><div class="cardbody"><div class="eyebrow">TRAVEL WITH KATIE + EVA</div><h3>The Spanish Offseason</h3><p class="muted small">Six nights on the Costa Blanca.<br>Tennis together. Room for your own pace.</p><div class="divider"></div><p class="small">From $2,995 per player<br><span class="muted">Illustrative shared-room starting estimate.</span></p><p class="small muted">Courtside handles the planning, coordination and support.</p></div></aside>`}
function supportPanel(){return `<aside><section class="panel"><div class="eyebrow">YOUR COURTSIDE CONTACT</div><h3>We’ve got<br>the details.</h3><p class="muted small">Jeffery · sample trip lead<br>Local support · assignment to confirm</p><p class="small muted">Your hosts enjoy the week with you. Courtside handles arrangements, changes and questions.</p><div class="actions">${route()==='host-desk'?'<button class="btn full" onclick="hostQuestion()">Contact the trip lead ↗</button>':link('help','Ask Courtside ↗','btn full')}</div></section><div class="demo-note">Support channels and staffed hours would be confirmed before travel. This prototype does not provide live assistance.</div></aside>`}
function shell(title,eyebrow,body,subtitle='',actions=''){return `<section class="workspace"><div class="workspace-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p class="muted small">${subtitle}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>${body}</section>`}
function personName(p){return p?.name||'Traveler'}
function findTraveler(id){return state.matchTraveler?.id===id?state.matchTraveler:state.group?.attendees.find(p=>p.id===id)}
function current(){return findTraveler(state.active)||state.group?.attendees[0]}
function groupDate(){if(state.active==='matched-riley'&&state.matchTraveler?.matchedDate&&!['group','host-desk','operations'].includes(route())&&!route().startsWith('operations/'))return state.matchTraveler.matchedDate;return state.group?.chosenDate||state.group?.weeks.find(d=>d!=='Flexible')||'Feb 7–13'}
function groupLabel(){return state.group?.name||'Your Spain group'}
function activeRequests(p=current()){return state.requests.filter(r=>r.travelerId===p?.id)}
function statusBadge(s){return badge(s,(/await|need|invited|undecided|received|approval/i.test(s)?'warn':/declined|unavailable|canceled|withdrawn/i.test(s)?'rust':/draft|not started|not invited/i.test(s)?'gray':''))}
function seedGroup(){return {id:'CS-2027-001',name:'Alex’s Spain group',organizerName:'Alex Example',organizerEmail:'alex@example.com',weeks:['Feb 7–13'],chosenDate:'Feb 7–13',players:'6',partners:'2',tennis:'Daily tennis',notes:'A week together with time for individual interests.',stage:'Planning',reviewed:false,paymentMode:'Individual travelers',attendees:[
{id:'alex',name:'Alex Example',email:'alex@example.com',role:'Organizer + player',invited:true,participation:'Interested',complete:true,room:'Shared room',roommate:'Sam',tennis:'Daily tennis',level:'3.5',interests:['Food + wine'],care:'',proposal:'Draft',payment:'Not due',arrival:null},
{id:'sam',name:'Sam Example',email:'sam@example.com',role:'Player',invited:true,participation:'Interested',complete:true,room:'Shared room',roommate:'Alex',tennis:'Extra tennis',level:'4.0',interests:['Extra tennis'],care:'',proposal:'Draft',payment:'Not due',arrival:null},
{id:'jordan',name:'Jordan Example',email:'jordan@example.com',role:'Player',invited:true,participation:'Interested',complete:false,room:'Help me decide',roommate:'',tennis:'Four mornings',level:'Not sure yet',interests:['Golf'],care:'',proposal:'Draft',payment:'Not due',arrival:null},
{id:'taylor',name:'Taylor Example',email:'taylor@example.com',role:'Player',invited:true,participation:'Awaiting response',complete:false,room:'Help me decide',tennis:'Four mornings',interests:['More downtime'],proposal:'Draft',payment:'Not due'},
{id:'guest5',name:'Guest 5 · sample',email:'guest5@example.com',role:'Player',invited:true,participation:'Still deciding',complete:false,room:'Help me decide',tennis:'Help me decide',interests:[],proposal:'Draft',payment:'Not due'},
{id:'guest6',name:'Guest 6 · sample',email:'',role:'Player',invited:false,participation:'Not invited',complete:false,room:'Help me decide',tennis:'Help me decide',interests:[],proposal:'Draft',payment:'Not due'},
{id:'partner1',name:'Partner 1 · sample',email:'partner1@example.com',role:'Non-playing partner',invited:true,participation:'Still deciding',complete:false,room:'Help me decide',tennis:'Non-playing partner',interests:['Spa + massage'],proposal:'Draft',payment:'Not due'},
{id:'partner2',name:'Partner 2 · sample',email:'',role:'Non-playing partner',invited:false,participation:'Not invited',complete:false,room:'Help me decide',tennis:'Non-playing partner',interests:[],proposal:'Draft',payment:'Not due'}]}}
function ensureGroup(){if(!state.group){state.group=seedGroup();state.active='alex';persist()}return state.group}
function performLoadStory(dest='group'){tab='Overview';tripPhase='Before travel';day=2;state.group=seedGroup();state.active='alex';state.requests=[];state.tasks=[];state.match=null;state.matchTraveler=null;state.activity=[];log('Sample group loaded for walkthrough.');persist();go(dest)}
function stageSample(){ensureGroup();state.group.stage='Confirmed';state.group.attendees.filter(p=>p.participation==='Interested').forEach(p=>{p.proposal='Confirmed';p.payment='Sample paid'});state.hostApproved=true;state.suppliers.forEach(s=>s.status='Confirmed');persist();go('trip-home')}
function navigateTab(value){tab=value;render()}
function rolebar(){ensureGroup();return `<div class="accountbar"><span><strong>Demo perspective</strong> · Viewing one traveler’s private experience</span><label style="margin:0;font-size:0">Choose sample traveler<select aria-label="Choose sample traveler" onchange="state.active=this.value;persist();render()">${[...state.group.attendees.filter(p=>!p.removed),...(state.matchTraveler?[state.matchTraveler]:[])].map(p=>`<option value="${esc(p.id)}" ${state.active===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div>`}
function captureDraft(form){for(const [k,v]of new FormData(form))if(k!=='week')state.draft[k]=v;if(form.querySelector('[name=week]'))state.draft.weeks=[...form.querySelectorAll('[name=week]:checked')].map(n=>n.value);persist()}
function start(){state.draft.step=1;persist();return `<div class="flow"><div class="flow-main"><div class="breadcrumb">${link('trip','← The experience','')}</div><div class="eyebrow">YOUR WEEK STARTS HERE</div><h1>How would you<br>like to come?</h1><p class="muted">Bring your people, or let us help you find good company.</p><a class="pathcard" href="#/request/group"><span class="arrow">↗</span><h3>Bring my own group</h3><p>I’m gathering tennis friends for a private week.</p><span class="tag" style="margin-top:14px">4–12 PLAYERS · PARTNERS WELCOME</span></a><a class="pathcard" href="#/request/match"><span class="arrow">↗</span><h3>Help me find a group</h3><p>I’m coming solo, as a couple or with a few friends.</p><span class="tag" style="margin-top:14px">DATES + TENNIS + GOOD COMPANY</span></a>${note('You’re expressing interest. No rooms or places are reserved at this stage.')}</div>${aside()}</div>`}
function requestPage(){const d=state.draft,group=d.path==='group',step=d.step;let body='';if(step===1)body=`<h1>Which weeks<br>could work?</h1><p class="muted">Choose every week you could travel. Availability below is illustrative.</p><div class="options">${dates.map((v,i)=>`<label class="option ${i===0?'disabled':''}"><input type="checkbox" name="week" value="${v}" ${d.weeks.includes(v)?'checked':''} ${i===0?'disabled':''}>${v}<small>${i===0?'Unavailable in this example':'Available to request · 2027'}</small></label>`).join('')}</div><label class="option" style="margin-top:10px"><input type="checkbox" name="week" value="Flexible" ${d.weeks.includes('Flexible')?'checked':''}>I’m flexible—help me choose</label><p class="fieldhint">If your first choice is unavailable, we’ll discuss alternatives before you commit.</p>`;
else if(step===2)body=`<h1>${group?'Who’s coming<br>with you?':'A little about<br>your party.'}</h1><p class="muted">${group?'Approximate numbers are perfect. You can invite everyone to share their own details afterward.':'Tell us what would make a week with others work for you.'}</p>${group?`<div class="two"><label>Tennis players${select('players',['Not sure yet','4','5','6','7','8','9','10','11','12'],d.players)}</label><label>Possible non-playing partners${select('partners',['Not sure yet','0','1','2','3','4','5','6'],d.partners)}</label></div>`:`<label>Your party${select('party',['Solo','Couple','2–3 friends'],d.party)}</label><label>Tennis level${select('level',['Not sure yet','2.5','3.0','3.5','4.0','4.5','5.0+'],d.level)}</label>`}<label>Ideal tennis rhythm${select('tennis',['Help us decide','A few relaxed mornings','Four mornings','Daily tennis','As much as possible'],d.tennis)}</label>${note(group?'You coordinate the group. Courtside follows up with each traveler about rooms, activities and personal arrangements.':'We personally review dates and tennis preferences. A request does not guarantee a matched departure.')}`;
else if(step===3)body=`<h1>Let’s make<br>the introduction.</h1><p class="muted">We’ll review your request and help with the next step.</p>${field('name',group?'Your name · group organizer':'Your name',d.name,'text',true,'Alex Example')}${field('email','Your email',d.email,'email',true,'alex@example.com')}<label>Anything you’d like us to know? <span class="muted">Optional</span><textarea name="notes" placeholder="A special occasion, a question or the week you imagine.">${esc(d.notes)}</textarea></label>${note('Use fictional details for the walkthrough. Information is saved only in this browser; nothing is sent.')}`;
else body=`<h1>The beginning<br>of a good week.</h1><p class="muted">Review your request before we take the next step.</p><div class="review"><div class="row"><span>Trip</span><strong>Spain with Katie + Eva</strong></div><div class="row"><span>Possible dates</span><span>${esc(d.weeks.join(', '))}</span></div><div class="row"><span>Party</span><span>${group?`${esc(d.players)} players<br>Partners: ${esc(d.partners)}`:esc(d.party)}</span></div><div class="row"><span>Tennis</span><span>${esc(d.tennis)}</span></div><div class="row"><span>Contact</span><span>${esc(d.name)}<br>${esc(d.email)}</span></div></div>${note('This is an inquiry, not a reservation. Courtside would check availability and prepare a proposal before any booking commitment.')}<label class="option"><input type="checkbox" required>I understand this is a simulated request.</label>`;
return `<div class="flow"><div class="flow-main"><div class="eyebrow">${group?'PRIVATE GROUP':'GROUP MATCH'} · ${step===4?'REVIEW':`STEP ${step} OF 3`}</div><div class="progress">${[1,2,3,4].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><form data-draft="true" onsubmit="submitInquiry(event)">${body}<div class="flow-buttons"><button type="button" class="back" onclick="backInquiry(this.form)">← Back</button><button class="btn">${step===4?'Send demo request':'Continue'} ↗</button></div></form></div>${aside()}</div>`}
function backInquiry(form){captureDraft(form);if(state.draft.step===1)go('start');else{state.draft.step--;persist();render();window.scrollTo(0,0)}}
function submitInquiry(e){e.preventDefault();const f=e.target;captureDraft(f);if(state.draft.step===1&&!state.draft.weeks.length)return toast('Choose a week, or select “I’m flexible.”');if(state.draft.step<4){state.draft.step++;persist();render();window.scrollTo(0,0);return}const d=state.draft;
if(d.path==='group'){if(state.group){modal('Start a new group',`<div class="eyebrow">LOCAL DEMO RECORD</div><h2>Start your new group?</h2><p class="muted small">This replaces the current sample group in this browser. No real invitations or bookings are affected.</p><div class="actions"><button class="btn" onclick="closeModal();completeGroupInquiry()">Create my demo group ↗</button><button class="outline" onclick="closeModal()">Keep current group</button></div>`);return}completeGroupInquiry()}
else{state.match={id:'CS-MATCH-001',name:d.name,email:d.email,weeks:[...d.weeks],party:d.party,level:d.level,tennis:d.tennis,notes:d.notes,status:'Reviewing possible weeks',proposedDate:'',proposalPrice:2995,history:[{text:'Request received. Dates and tennis preferences ready for review.',time:stamp()}]};log('Group-matching inquiry received from '+d.name+'.');persist();go('match-home')}}
function receipt(){const g=ensureGroup();return `<section class="success"><div class="center"><div class="successmark">✓</div><div class="eyebrow">REQUEST RECEIVED · ${esc(g.id)}</div><h1>Your group<br>starts here.</h1><p class="muted">${esc(g.organizerName.split(' ')[0])}, we have the beginning of your Spain week. Next, invite your people so Courtside can take care of each traveler directly.</p><div class="review"><div class="row"><span>Dates</span><span>${esc(g.weeks.join(', '))}</span></div><div class="row"><span>Expected party</span><span>${esc(g.players)} players<br>Possible partners: ${esc(g.partners)}</span></div><div class="row"><span>Next with Courtside</span><span>Review dates and availability</span></div></div><div class="actions">${link('group','Open your group ↗')}${link('operations','See it arrive with Courtside','outline')}</div>${note('Demo receipt. No email was sent. Your group page is saved in this browser, and adding attendees does not reserve places.')}</div></section>`}
function modal(title,body){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modalveil" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="modalclose" aria-label="Close dialog" onclick="closeModal()">×</button>${body}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay').querySelector('input,select,button')?.focus(),0)}
function closeModal(){document.body.style.overflow='';$('#overlay').innerHTML='';lastFocus?.focus?.()}
document.addEventListener('keydown',e=>{if(!$('#overlay').firstChild)return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const all=[...$('#overlay').querySelectorAll('button,a[href],input,select,textarea')].filter(el=>!el.disabled);if(!all.length)return;const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function addAttendeeModal(){modal('Add an attendee',`<div class="eyebrow">YOUR GROUP</div><h2>Who’s joining you?</h2><p class="muted small">Add one person at a time. They can choose their own room, tennis and interests.</p><form onsubmit="addAttendee(event)">${field('name','Attendee name','','text',true,'Sam Example')}${field('email','Email address · optional for now','','email',false,'sam@example.com')}<label>Traveling as${select('role',['Player','Non-playing partner'],'Player')}</label>${note('Adding a name does not send an invitation. Review and send it from your group page. Use sample details.')}<button class="btn full" style="margin-top:20px">Add to my group ↗</button></form>`)}
function addAttendee(e){e.preventDefault();const f=new FormData(e.target);const email=String(f.get('email')).trim().toLowerCase();if(email&&state.group.attendees.some(p=>!p.removed&&p.email.toLowerCase()===email))return toast('That email is already in your group.');const p={id:uid('guest'),name:String(f.get('name')).trim(),email,role:f.get('role'),invited:false,participation:'Not invited',complete:false,room:'Help me decide',roommate:'',tennis:f.get('role')==='Non-playing partner'?'Non-playing partner':'Help me decide',interests:[],proposal:'Draft',payment:'Not due'};state.group.attendees.push(p);log('Attendee added: '+p.name+'. Invitation not sent.');persist();closeModal();render();toast('Attendee added. You can now review their invitation.')}
function invitationModal(id){const p=state.group.attendees.find(x=>x.id===id);if(!p)return;modal('Review invitation',`<div class="eyebrow">REVIEW BEFORE SENDING</div><h2>An invitation<br>to your people.</h2><form onsubmit="sendInvite(event,'${p.id}')">${field('email','Send to',p.email,'email',true,'sam@example.com')}<div class="invitation-card"><p class="serif">${esc(state.group.organizerName.split(' ')[0])} is planning a week in Spain with Katie + Eva.</p><p class="small muted">${esc(p.name)}, you’re invited to join the planning. Tell Courtside whether you’re interested and what would make the week work for you.</p></div>${note('This simulates an invitation. No email will be sent. Afterward, preview the attendee’s experience here.')}<button class="btn full">${p.invited?'Resend demo invitation':'Send demo invitation'} ↗</button></form>`)}
function sendInvite(e,id){e.preventDefault();const p=state.group.attendees.find(x=>x.id===id);p.email=new FormData(e.target).get('email').trim();p.invited=true;p.invitationCanceled=false;if(p.participation==='Not invited'||p.participation==='Invitation canceled')p.participation='Awaiting response';p.sentAt=stamp();log('Demo invitation '+(p.sentBefore?'resent':'sent')+' to '+p.name+'.');p.sentBefore=true;persist();closeModal();render();toast('Demo invitation ready. Use “Preview attendee” to open it.')}
function cancelInvite(id){if(!confirm('Cancel this pending demo invitation?'))return;const p=state.group.attendees.find(x=>x.id===id);p.invited=false;p.invitationCanceled=true;p.participation='Invitation canceled';log('Invitation canceled for '+p.name+'.');persist();render()}
function removeAttendee(id){if(!confirm('Remove this attendee from the demo group?'))return;const p=state.group.attendees.find(x=>x.id===id);p.removed=true;log(p.name+' removed from the group.');if(state.active===id)state.active=state.group.attendees.find(x=>!x.removed)?.id;persist();render()}
function previewAttendee(id){state.active=id;persist();go('attendee/'+id)}
async function copyText(s,message){try{await navigator.clipboard.writeText(s);toast(message)}catch{modal('Copy link',`<h2>Your invitation.</h2><p class="muted small">Copy the text below.</p><label>Invitation<input readonly value="${esc(s)}" onclick="this.select()"></label>`)} }
function copyGroupLink(){const url=location.href.split('#')[0]+'#/join-group';copyText(url,'Sample planning link copied. Demo records are local to this browser.')}
function groupPage(){const g=ensureGroup(),people=g.attendees.filter(p=>!p.removed),interested=people.filter(p=>p.participation==='Interested').length,complete=people.filter(p=>p.complete).length,needed=people.filter(p=>!p.invited).length;const body=`${progress(g.stage)}<div class="callout"><div class="eyebrow">BRING YOUR PEOPLE. WE’LL HANDLE THEIR DETAILS.</div><h3>Who’s joining you?</h3><p>Invite each traveler to respond and plan their own stay. Courtside follows up with them directly.</p><div class="actions"><button class="btn" onclick="addAttendeeModal()">Add an attendee +</button><button class="outline" onclick="copyGroupLink()">Copy planning link ↗</button></div></div><div class="split"><div><section class="panel"><div class="panelhead"><h3>Your people.</h3>${badge(people.length+' listed')}</div><div class="tally"><div><strong>${interested}</strong>Interested</div><div><strong>${complete}</strong>Details complete</div><div><strong>${needed}</strong>Need invitation</div></div>${people.map(p=>`<article class="attendee"><div class="person"><span class="initial">${esc(p.name[0])}</span><div class="namewrap"><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></div></div><div class="attendee-status">${statusBadge(p.participation)}<span class="small muted">${p.complete?'Planning details complete':p.participation==='Not attending'?'No place requested':'Details not complete'}</span></div><div class="buttons">${p.role.startsWith('Organizer')?`<button class="plain" onclick="state.active='${p.id}';persist();go('preferences')">My details ↗</button>`:`<button class="plain" onclick="invitationModal('${p.id}')">${p.invited?'Resend invitation':'Review invitation'} ↗</button>${p.invited?`<button class="plain" onclick="previewAttendee('${p.id}')">Preview attendee ↗</button>`:''}${p.invited&&p.participation==='Awaiting response'?`<button class="plain danger" onclick="cancelInvite('${p.id}')">Cancel invite</button>`:''}<button class="plain danger" onclick="removeAttendee('${p.id}')">Remove</button>`}</div></article>`).join('')}<p class="fieldhint">You see participation and planning progress. Personal requirements and conversations are handled privately with Courtside.</p></section><section class="panel"><div class="eyebrow">SHARED DECISIONS</div><h3>The week you’re shaping.</h3><div class="listrow"><span>Preferred dates</span><span>${esc(g.weeks.join(', '))}</span></div><div class="listrow"><span>Target group</span><span>${esc(g.players)} players · Partners: ${esc(g.partners)}</span></div><div class="listrow"><span>Tennis rhythm</span><span>${esc(g.tennis)}</span></div><div class="listrow"><span>Payment responsibility</span><span>${esc(g.paymentMode)}</span></div><div class="actions"><button class="outline mini" onclick="editGroupModal()">Update group preferences</button>${g.stage==='Proposal'||g.stage==='Confirmed'?link('proposal','Review proposal ↗','btn mini'):link('help','Ask a group question ↗','soft mini')}</div></section></div><aside><section class="panel">${tripmini()}<div class="divider"></div><div class="eyebrow">WHAT HAPPENS NEXT</div><p class="small muted">Courtside reviews your dates and availability while your group comes together. We then prepare a proposal with clear individual arrangements and costs.</p><div class="actions">${link('operations','Preview team follow-up ↗','textlink')}</div></section>${note('Organizer view · local demonstration. Sharing this prototype does not send or synchronize private invitations across browsers.')}</aside></div>`;return shell(esc(g.name),'YOUR GROUP · '+esc(g.id),body,'You gather your friends. Courtside takes care of each traveler.',link('trip-home','My trip home ↗','outline mini'))}
function editGroupModal(){const g=state.group;modal('Group preferences',`<div class="eyebrow">GROUP PREFERENCES</div><h2>Keep us in the loop.</h2><form onsubmit="saveGroup(event)">${field('name','Group name',g.name,'text',true)}<label>Preferred week${select('date',['Flexible',...dates.slice(1)],groupDate())}</label><label>Tennis rhythm${select('tennis',['Help us decide','A few relaxed mornings','Four mornings','Daily tennis','As much as possible'],g.tennis)}</label><label>Who plans to pay?${select('paymentMode',['Individual travelers','Organizer requests group payment'],g.paymentMode)}</label>${note('Changes after a proposal or confirmation require review. Updating a preference does not change a booking.')}<button class="btn full">Save preferences ↗</button></form>`)}
function saveGroup(e){e.preventDefault();const f=new FormData(e.target),g=state.group;g.name=f.get('name');g.weeks=[f.get('date')];g.tennis=f.get('tennis');g.paymentMode=f.get('paymentMode');g.changeReview=true;log('Organizer updated group preferences; Courtside review needed.');persist();closeModal();render();toast('Preferences saved. Courtside review added.')}
function attendeePage(id){ensureGroup();const p=state.group.attendees.find(x=>x.id===id&&!x.removed);if(!p)return shell('This invitation<br>needs a fresh link.','YOUR INVITATION',`<section class="panel"><p class="muted">This prototype stores attendee records in the browser where they were created. Ask the organizer for a fresh invitation in the live service.</p><div class="actions"><button class="btn" onclick="loadStory('group')">Explore with sample travelers ↗</button>${link('guide','Walkthrough guide','outline')}</div></section>`);state.active=p.id;persist();if(p.invitationCanceled)return shell('This invitation<br>has been canceled.','YOUR INVITATION',`<section class="panel"><p class="muted">The organizer can send you a new invitation if plans change.</p>${link('group','Return to organizer view ↗','textlink')}</section>`);return shell('A good week.<br>With your people.','YOU’RE INVITED',`<div class="focuslayout"><section class="panel">${tripmini()}<div class="divider"></div><h3>${esc(p.name.split(' ')[0])}, you’re invited.</h3><p class="muted">${esc(state.group.organizerName.split(' ')[0])} is planning a Spain week with Katie and Eva. Tell us where you stand, and Courtside will help with the details.</p><div class="actions"><button class="btn" onclick="respond('${p.id}','Interested')">I’m interested ↗</button><button class="outline" onclick="respond('${p.id}','Still deciding')">Still deciding</button><button class="back" onclick="respond('${p.id}','Not attending')">Unable to join</button></div>${p.participation!=='Awaiting response'&&p.participation!=='Not invited'?`<p class="small muted">Your current response: ${esc(p.participation)}. You can update it here.</p>`:''}${note('Responding does not reserve a place or commit you to payment. Demo responses update the organizer and team views in this browser.')}</section>${aside()}</div>`,'An invitation to join the planning, at your own pace.')}
function respond(id,value){const p=state.group.attendees.find(x=>x.id===id);p.participation=value;p.invited=true;state.active=id;log(p.name+' responded: '+value+'.');persist();if(value==='Not attending'){go('attendee-thanks');return}go('preferences')}
function attendeeThanks(){return shell('Thanks for<br>letting us know.','RESPONSE SAVED',`<section class="panel"><p class="muted">The group’s progress has been updated. You can return to your invitation if your plans change.</p><div class="actions">${link('attendee/'+state.active,'Review my response','outline')}${link('group','Preview organizer progress ↗')}</div></section>`)}
function preferences(){ensureGroup();const p=current(),interests=['Extra tennis','Golf','Spa + massage','Food + wine','Coastal exploring','Padel','More downtime'];return shell('Make it<br>your week.','PERSONAL PLANNING',`${rolebar()}<div class="split"><section class="panel"><div class="eyebrow">${esc(p.name)} · PRIVATE DETAILS</div><h3>A few personal touches.</h3><p class="muted small">Your preferences help Courtside prepare options. Nothing extra is booked without your approval.</p><form data-preferences="${p.id}" onsubmit="savePreferences(event,true)"><div class="formgrid"><label>Your participation${select('participation',['Interested','Still deciding','Not attending'],p.participation==='Awaiting response'||p.participation==='Not invited'?'Still deciding':p.participation)}</label><label>Traveling as${select('role',['Player','Non-playing partner'],p.role==='Non-playing partner'?'Non-playing partner':'Player')}</label><label>Tennis level${select('level',['Not sure yet','2.5','3.0','3.5','4.0','4.5','5.0+'],p.level||'Not sure yet')}</label><label>Ideal tennis${select('tennis',['Help me decide','Four mornings','Daily tennis','Extra tennis','A lighter schedule','Non-playing partner'],p.tennis||'Help me decide')}</label></div><label>Room preference${select('room',['Help me decide','Shared room','Private room','Interested in an upgrade'],p.room||'Help me decide')}</label>${field('roommate','Roommate request · optional',p.roommate||'','text',false,'Someone you’re traveling with')}<p class="fieldhint">A roommate request is provisional until everyone and Courtside agree.</p><label>What sounds good?</label><div class="options">${interests.map(i=>`<label class="option"><input type="checkbox" name="interests" value="${i}" ${(p.interests||[]).includes(i)?'checked':''}>${i}</label>`).join('')}</div><label>Anything that helps us take care of you? <span class="muted">Optional</span><textarea name="care" placeholder="For this public demo, use fictional details only. In the live service, relevant dietary and accessibility requirements are shared privately with Courtside.">${esc(p.care||'')}</textarea></label>${note('Use fictional details only. The perspective switcher is for demonstration; it is not production access control.')}<div class="actions"><button class="btn">Save my preferences ↗</button><button class="outline" type="button" onclick="savePreferences({target:this.form,preventDefault(){}},false)">Save and finish later</button></div></form></section>${supportPanel()}</div>`,'Everyone chooses their own stay. Courtside coordinates the pieces.')}
function savePreferences(e,complete){e.preventDefault();const form=e.target,p=findTraveler(form.dataset.preferences),f=new FormData(form);const organizer=p.role.startsWith('Organizer');['participation','level','tennis','room','roommate','care'].forEach(k=>p[k]=f.get(k)||'');p.role=organizer?'Organizer + '+(f.get('role')==='Player'?'player':'partner'):f.get('role');p.interests=f.getAll('interests');if(f.get('role')==='Non-playing partner')p.tennis='Non-playing partner';p.complete=complete;p.invited=true;log(p.name+(complete?' completed personal planning.':' saved planning progress.'));persist();toast(complete?'Preferences saved. Organizer and team progress updated.':'Progress saved. You can return later.');go('planning-saved')}
function planningSaved(){const p=current();return `<section class="success"><div class="center"><div class="successmark">✓</div><div class="eyebrow">${p.complete?'PREFERENCES SAVED':'PROGRESS SAVED'}</div><h1>${p.complete?'Your kind<br>of week.':'Pick it up<br>when you’re ready.'}</h1><p class="muted">Courtside has your sample preferences. The organizer can see your progress, while personal details stay with the trip team in the live experience.</p><div class="actions">${link('trip-home','Open my trip home ↗')}${link('group','Preview organizer progress','outline')}</div>${note()}</div></section>`}
function joinGroup(){ensureGroup();return shell('You’re invited<br>to the planning.','SHARED GROUP INVITATION',`<div class="focuslayout"><section class="panel">${tripmini()}<p class="muted">Join the sample group to share your own preferences. This does not confirm attendance or reserve a place.</p><form onsubmit="joinGroupSubmit(event)">${field('name','Your name','','text',true,'New Guest')}${field('email','Your email','','email',true,'guest@example.com')}<label>Traveling as${select('role',['Player','Non-playing partner'],'Player')}</label><button class="btn" style="margin-top:22px">Join the demo planning ↗</button></form>${note('Prototype link: group records are local to this browser. In the live service, this would identify the organizer’s actual group without exposing its private details.')}</section>${aside()}</div>`)}
function joinGroupSubmit(e){e.preventDefault();const f=new FormData(e.target),email=f.get('email').trim().toLowerCase();let p=state.group.attendees.find(x=>!x.removed&&x.email.toLowerCase()===email);if(!p){p={id:uid('guest'),name:f.get('name'),email,role:f.get('role'),invited:true,participation:'Interested',complete:false,room:'Help me decide',tennis:'Help me decide',interests:[],proposal:'Draft',payment:'Not due'};state.group.attendees.push(p)}state.active=p.id;log(p.name+' joined planning through the sample shared link.');persist();go('preferences')}
function priceFor(p){return p.role.includes('partner')?1995:2995}
function proposal(){ensureGroup();const p=current(),base=priceFor(p),sent=p.proposal!=='Draft';return shell('Your week,<br>coming together.','PERSONAL PROPOSAL · SAMPLE',`${rolebar()}<div class="split"><section class="panel">${tripmini()}<div class="divider"></div><div class="row"><h3>${esc(p.name.split(' ')[0])}’s arrangements.</h3>${statusBadge(p.proposal||'Draft')}</div>${!sent?note('This is a draft preview. To simulate sending it, use Courtside team → Group & guests → Send sample proposals.'):''}<div class="review"><div class="row"><span>Proposed dates</span><span>${esc(groupDate())}, 2027</span></div><div class="row"><span>Stay</span><span>6 nights · shared Deluxe room</span></div><div class="row"><span>Room preference</span><span>${esc(p.room)}${p.room==='Private room'?'<br>Supplement requires quote':''}</span></div><div class="row"><span>Hosted experience</span><span>${p.role.includes('partner')?'Shared meals + group highlights':'Four mornings with Katie + Eva<br>Welcome + farewell dinners'}</span></div><div class="row"><span>Base example price</span><strong>$${base.toLocaleString()} per traveler</strong></div><div class="row"><span>Extras</span><span>Quoted separately, with approval</span></div><div class="row"><span>Payment responsibility</span><span>${esc(state.group.paymentMode)}<br>${state.group.paymentMode==='Individual travelers'?'You pay for your own arrangements.':'Group-payer arrangement needs agreement.'}</span></div></div><h3>Clear before you commit.</h3><p class="muted small">The example base includes six nights, breakfast, scheduled club transfers, the stated hosted program and Courtside coordination. Airfare, room supplements, personal spending and optional activities are excluded.</p><p class="muted small">Private-room supplements, additional tennis and upgrades are requests until separately quoted. Roommate preferences require agreement.</p>${note('Sample proposal, not a verified quote. Final supplier availability, complete pricing, payment schedule and cancellation terms must be established before any real commitment.')}<div class="actions">${p.proposal==='Confirmed'?link('trip-home','Open confirmed trip ↗'):p.proposal==='Payment pending'?link('payment','Continue sample confirmation ↗'):p.proposal==='Review requested'?`<span class="badge warn">Courtside is reviewing your question</span>`:`<button class="btn" onclick="acceptSampleProposal()">Continue sample confirmation ↗</button>`}<button class="outline" onclick="go('help/new/proposal')">Ask about this proposal</button></div><p class="fieldhint">Changes to room, tennis or requested dates require a fresh review before a real quote. Continuing simulates a confirmation process. It does not accept legal terms or collect money.</p></section>${supportPanel()}</div>`,'Personal arrangements and costs, with shared decisions kept clear.')}
function acceptSampleProposal(){const p=current();p.proposal='Payment pending';p.payment='Sample payment pending';log(p.name+' entered sample confirmation.');persist();go('payment')}
function payment(){ensureGroup();const p=current();return shell('One clear<br>confirmation.','SIMULATED PAYMENT STEP',`<div class="focuslayout"><section class="panel"><div class="eyebrow">${esc(p.name)} · ${esc(groupDate())}</div><h3>Your example summary.</h3><div class="review"><div class="row"><span>Shared-room base</span><strong>$${priceFor(p).toLocaleString()}</strong></div><div class="row"><span>Payment details</span><span>No card details collected</span></div><div class="row"><span>Booking terms</span><span>Not established in this prototype</span></div></div>${note('This button creates a sample confirmed state only. No money moves, no legal agreement is accepted and no supplier booking is made.')}<button class="btn full" onclick="confirmTraveler()">Simulate confirmation ↗</button><div class="actions">${link('proposal','← Review proposal','textlink')}</div></section>${aside()}</div>`)}
function confirmTraveler(){tab='Overview';tripPhase='Before travel';const p=current();p.proposal='Confirmed';p.payment='Sample paid';if(p.id!=='matched-riley')state.group.stage='Confirmed';log(p.name+' entered sample confirmed state.');persist();go('trip-home');toast('Sample trip confirmed. Nothing has been charged or booked.')}
function tripHome(){ensureGroup();const p=current(),confirmed=p.proposal==='Confirmed';const body=`${rolebar()}<div class="accountbar"><span>Preview the guest experience</span><label style="margin:0;font-size:0">Travel phase<select aria-label="Travel phase" onchange="tripPhase=this.value;render()">${['Before travel','During the trip','After the trip'].map(x=>`<option ${tripPhase===x?'selected':''}>${x}</option>`).join('')}</select></label></div>${tripPhase==='After the trip'?afterTrip(p):tripPhase==='During the trip'?duringTrip(p):`<nav class="tabs" aria-label="Trip home sections">${['Overview','My plans','Our group','Arrangements','Help'].map(t=>`<button class="${tab===t?'selected':''}" onclick="navigateTab('${t}')">${t}</button>`).join('')}</nav>${tab==='Overview'?overview(p,confirmed):tab==='My plans'?itinerary(p):tab==='Our group'?travelerGroup():tab==='Arrangements'?arrangements(p):helpBody()}`}
`;return shell(confirmed?'Your week<br>is waiting.':'Your week,<br>taking shape.',confirmed?'PRIVATE TRIP HOME · SAMPLE CONFIRMED':'YOUR PLANNING HOME',body,`${esc(p.name)} · Spain with Katie + Eva · ${esc(groupDate())}, 2027`,statusBadge(confirmed?'Sample confirmed':state.group.stage))}
function overview(p,confirmed){const rs=activeRequests(p),pending=rs.filter(r=>!['Confirmed','Declined','Canceled','Unavailable'].includes(r.status));return `<div class="split"><div>${!confirmed?`<div class="callout"><div class="eyebrow">YOUR NEXT STEP</div><h3>${p.complete?'Review how your week could come together.':'Tell us what makes it your week.'}</h3><p>${p.complete?'Courtside checks availability and prepares a proposal. You can preview the proposal in this walkthrough.':'Room, tennis and personal interests. You can save and return at any time.'}</p><div class="actions">${link(p.complete?'proposal':'preferences',p.complete?'Preview my proposal ↗':'Complete my preferences ↗')}</div></div>`:`<div class="callout"><div class="eyebrow">YOU’RE IN · SAMPLE STATE</div><h3>We’ll take care of the details.</h3><p>${p.arrival?'Your sample arrival is saved. Your next plans and any open requests are below.':'Share your arrival information when you’re ready. We’ll use it to coordinate transport.'}</p><div class="actions">${p.arrival?`<button class="btn" onclick="navigateTab('My plans')">View my plans ↗</button>`:link('arrival','Add arrival details ↗')}</div></div>`}<section class="panel"><div class="eyebrow">BEFORE YOU GO</div><h3>${p.complete&&p.arrival&&!pending.length?'A little more to look forward to.':'A few useful next steps.'}</h3><div class="task"><div><strong>Your preferences</strong><p>${p.complete?'Saved. You can review them anytime.':'Rooms, tennis and interests, privately with Courtside.'}</p></div>${link('preferences',p.complete?'Review ↗':'Start ↗','soft mini')}</div><div class="task"><div><strong>Arrival details</strong><p>${p.arrival?esc(p.arrival.flight)+' · '+esc(p.arrival.date):'Flight information for transfer planning.'}</p></div>${link('arrival',p.arrival?'Edit ↗':'Add ↗','soft mini')}</div><div class="task"><div><strong>Your proposal</strong><p>${esc(p.proposal||'Draft')} · clear personal arrangements.</p></div>${link('proposal','View ↗','soft mini')}</div>${pending.map(r=>`<div class="task"><div><strong>${esc(r.subject)}</strong><p>${esc(r.status)}</p></div>${link('help/'+r.id,'Open ↗','soft mini')}</div>`).join('')}</section><div class="largepic">${img('coast.jpg','Katie and Eva, your hosts in Spain')}</div></div>${supportPanel()}</div>`}
const week=[{day:'Sun',date:'Arrival',title:'Arrive, exhale, meet the table.',events:[['Afternoon','Arrival + settle in','Personal arrangement','Your confirmed pickup and check-in instructions would appear here.'],['19:00','Welcome dinner with Katie + Eva','Shared event','Example meeting point: resort reception.']]},{day:'Mon',title:'Clay mornings. Open afternoons.',events:[['08:45','Club transfer','Shared event','Scheduled departure from the resort.'],['09:15','Tennis with Katie + Eva','Shared event','Four-morning base program · example schedule.'],['13:00','Your afternoon, your way','Free time','Lunch, resort time or optional interests.']]},{day:'Tue',title:'Your kind of afternoon.',events:[['08:45','Club transfer','Shared event','Meet at the agreed resort pickup point.'],['09:15','Tennis with Katie + Eva','Shared event','A morning together at Almoradí.'],['13:00','An open afternoon','Free time','Individual activities appear below when arranged.'],['Evening','Dinner at your own pace','Free time','Next shared session: Thursday morning.']]},{day:'Wed',title:'A little less scheduled.',events:[['All day','Make it your own','Free time','Golf, spa, exploring or absolutely nothing. Optional plans require confirmation.']]},{day:'Thu',title:'Back on court, together.',events:[['08:45','Club transfer','Shared event','Resort pickup · example schedule.'],['09:15','Tennis with Katie + Eva','Shared event','Shared coaching and match play.'],['Afternoon','Time to explore','Free time','Optional outings can be coordinated with Courtside.']]},{day:'Fri',title:'A few more hits. One last table.',events:[['09:15','Match play with Katie + Eva','Shared event','Final morning in the example base program.'],['19:00','Farewell dinner','Shared event','Katie + Eva join the group.']]},{day:'Sat',title:'Until next time.',events:[['Morning','Breakfast + departure','Personal arrangement','Your final transfer depends on your confirmed arrangements.']]}];
function itinerary(p){const extended=activeRequests(p).some(r=>r.status==='Confirmed'&&r.type==='Stay change');const days=extended&&scheduleMode==='personal'?[...week.slice(0,6),{day:'Sat',title:'A little longer in Spain.',events:[['All day','Your approved extra night','Personal arrangement','Sample accommodation extension confirmed. Your adjusted transfer is coordinated by Courtside.']]},{day:'Sun+',title:'Your adjusted departure.',events:[['Morning','Breakfast + departure','Personal arrangement','Your sample extra night and adjusted departure are included in the personal arrangements.']]}]:week;if(day>=days.length)day=2;const w=days[day];let events=w.events.filter(e=>!(p.role.includes('partner')&&scheduleMode==='personal'&&/Tennis|Club transfer|Match play/.test(e[1])));if(scheduleMode==='group')events=w.events.filter(e=>e[2]==='Shared event'||e[2]==='Free time');const confirmed=activeRequests(p).filter(r=>r.status==='Confirmed'),open=activeRequests(p).filter(r=>!['Confirmed','Declined','Canceled','Unavailable'].includes(r.status));return `<div class="split"><section class="panel"><div class="panelhead"><div><div class="eyebrow">${scheduleMode==='personal'?'YOUR INDIVIDUAL ITINERARY':'SHARED GROUP RHYTHM'}</div><h3>${w.title}</h3></div></div><div class="pilltabs"><button class="${scheduleMode==='personal'?'selected':''}" onclick="scheduleMode='personal';render()">My plans</button><button class="${scheduleMode==='group'?'selected':''}" onclick="scheduleMode='group';render()">Group plans</button></div><div class="weekdays">${days.map((w,i)=>`<button class="${i===day?'selected':''}" onclick="day=${i};render()">${w.day}</button>`).join('')}</div>${events.map(e=>`<div class="schedule"><div class="time">${e[0]}</div><div><h4>${e[1]}</h4><p>${e[3]}</p>${badge(e[2],e[2]==='Free time'?'gray':'')} ${e[2]!=='Free time'?badge(p.proposal==='Confirmed'?'Sample confirmed':'Illustrative · not booked',p.proposal==='Confirmed'?'':'warn'):''}</div></div>`).join('')}${scheduleMode==='personal'&&day===2?confirmed.filter(r=>r.type==='Activity').map(r=>`<div class="schedule"><div class="time">${esc(r.optionTime||'14:30')}</div><div><h4>${esc(r.subject)}</h4><p>${esc(r.offer)} · Personal arrangement</p>${badge('Sample confirmed')}</div></div>`).join(''):''}${scheduleMode==='personal'&&day===2&&p.interests?.includes('Golf')&&!activeRequests(p).some(r=>r.type==='Activity')?`<div class="schedule"><div class="time">Afternoon</div><div><h4>Golf sounds good?</h4><p>Your interest is saved. Ask Courtside to check an option.</p>${link('help/new/activity','Ask about golf ↗','textlink')}</div></div>`:''}<p class="fieldhint">${scheduleMode==='group'?'Private appointments are excluded. This view shows the common rhythm and intentional free time.':'Times and locations are illustrative. In the live service, this is the latest confirmed schedule.'}</p><div class="actions"><button class="outline mini" onclick="exportCalendar()">Add sample plans to calendar ↗</button></div></section><aside><section class="panel"><div class="eyebrow">YOUR PERSONAL ARRANGEMENTS</div><h3>Room for your own pace.</h3>${confirmed.length?confirmed.map(r=>`<div class="listrow"><span>${esc(r.subject)}<br><span class="muted">${esc(r.offer)}</span></span>${statusBadge(r.status)}</div>`).join(''):'<p class="muted small">No extra arrangements confirmed. Your interests are the beginning of a conversation.</p>'}${open.map(r=>`<div class="listrow"><span>${link('help/'+r.id,esc(r.subject),'textlink')}</span>${statusBadge(r.status)}</div>`).join('')}<div class="actions">${link('help/new/activity','Arrange something ↗','btn mini')}</div></section>${note('Calendar download contains sample confirmed shared events only. Requested extras are excluded until confirmed. A download is not a live calendar subscription.')}</aside></div>`}
function travelerGroup(){if(current()?.id==='matched-riley')return `<div class="split"><section class="panel"><div class="eyebrow">YOUR PROPOSED DEPARTURE</div><h3>A group taking shape.</h3><p class="muted small">${esc(state.match?.proposedDate||groupDate())}, 2027 · Spain with Katie + Eva. Courtside is reviewing compatibility, party size and final arrangements. This traveler is separate from the private Alex group.</p><div class="review"><div class="row"><span>Your party</span><span>${esc(state.match?.party||'Solo')}</span></div><div class="row"><span>Group character</span><span>Social tennis + independent afternoons · sample</span></div></div><div class="actions">${link('match-home','Review matching request ↗','outline')}${link('help','Ask about the group ↗')}</div></section>${supportPanel()}</div>`;return `<div class="split"><section class="panel"><div class="eyebrow">OUR GROUP</div><h3>Good company,<br>with space for everyone.</h3><p class="muted small">Shared decisions and group commitments live here. Personal care notes, appointments and costs are private in the intended service.</p><div class="review"><div class="row"><span>Organizer</span><span>${esc(state.group.organizerName)}</span></div><div class="row"><span>Dates</span><span>${esc(groupDate())}, 2027</span></div><div class="row"><span>Interested travelers</span><span>${state.group.attendees.filter(p=>!p.removed&&p.participation==='Interested').length}</span></div><div class="row"><span>Shared program</span><span>Four tennis mornings<br>Welcome + farewell dinners</span></div></div><div class="actions"><button class="btn" onclick="tab='My plans';scheduleMode='group';render()">See shared plans ↗</button>${link('group','Organizer demo view','outline')}</div></section>${supportPanel()}</div>`}
function arrangements(p){const extras=activeRequests(p).filter(r=>r.status==='Confirmed'),extraTotal=extras.reduce((a,r)=>a+Number(r.cost||0),0);return `<div class="split"><section class="panel"><div class="eyebrow">YOUR ARRANGEMENTS</div><h3>All in one place.</h3><div class="listrow"><span>Stay<br><span class="muted">La Finca Resort · sample shared Deluxe</span></span><span>6 nights${extras.some(r=>r.type==='Stay change')?' + approved extension':''}</span></div><div class="listrow"><span>Room preference<br><span class="muted">${esc(p.room)} · roommate ${esc(p.roommate||'to discuss')}</span></span>${badge('Requires final agreement','warn')}</div><div class="listrow"><span>Arrival<br><span class="muted">${p.arrival?esc(p.arrival.flight)+' · '+esc(p.arrival.time):'Details still needed'}</span></span>${link('arrival',p.arrival?'Edit ↗':'Add ↗','textlink')}</div><div class="listrow"><span>Base example price</span><strong>$${priceFor(p).toLocaleString()}</strong></div>${extras.map(r=>`<div class="listrow"><span>${esc(r.subject)}<br><span class="muted">Sample approved extra</span></span><strong>$${Number(r.cost).toLocaleString()}</strong></div>`).join('')}<div class="listrow"><span>Sample total<br><span class="muted">Base + confirmed extras; excludes unquoted room changes</span></span><strong>$${(priceFor(p)+extraTotal).toLocaleString()}</strong></div><div class="listrow"><span>Base payment status</span>${statusBadge(p.payment||'Not due')}</div>${extras.length?'<p class="fieldhint">Extra payment arrangements are to confirm. Approval does not charge a card.</p>':''}<div class="actions">${link('proposal','Review proposal ↗','outline mini')}${link('help/new/stay','Request a stay change ↗','btn mini')}</div>${note('Prices, payment states and confirmations are illustrative. No actual booking documents or commercial terms have been issued.')}</section>${supportPanel()}</div>`}
function arrival(){ensureGroup();const p=current(),a=p.arrival||{};return shell('A smooth start<br>to the week.','YOUR ARRIVAL',`<div class="focuslayout"><section class="panel"><p class="muted small">Share sample flight details so Courtside can demonstrate transfer coordination. Airport and transfer arrangements require agreement in the final proposal.</p><form onsubmit="saveArrival(event)">${field('airport','Arrival airport',a.airport||'Alicante · sample','text',true)}${field('flight','Flight number',a.flight||'','text',true,'AB123')}<div class="formgrid">${field('date','Arrival date',a.date||'2027-02-07','date',true)}${field('time','Local arrival time',a.time||'14:30','time',true)}</div>${note('Use sample travel details only. Saving creates a transport follow-up in the team workspace.')}<div class="actions"><button class="btn">Save arrival details ↗</button>${link('trip-home','Back','outline')}</div></form></section>${aside()}</div>`)}
function saveArrival(e){e.preventDefault();const f=new FormData(e.target),p=current();p.arrival=Object.fromEntries(f);state.tasks=state.tasks.filter(t=>!(t.kind==='arrival'&&t.travelerId===p.id));state.tasks.push({id:uid('task'),kind:'arrival',travelerId:p.id,title:'Review '+p.name+'’s arrival and transfer',owner:'Trip lead',due:'Before travel',done:false});log(p.name+' saved arrival details; transfer review needed.');persist();go('trip-home');toast('Arrival saved. Courtside has a transport follow-up.')}
function exportCalendar(){ensureGroup();if(current().proposal!=='Confirmed')return toast('Confirm the sample proposal first, then export confirmed plans.');let chosen=groupDate(),map={'Jan 17–23':'2027-01-17','Jan 24–30':'2027-01-24','Jan 31–Feb 6':'2027-01-31','Feb 7–13':'2027-02-07','Feb 14–20':'2027-02-14','Feb 21–27':'2027-02-21'};let start=new Date((map[chosen]||'2027-02-07')+'T00:00:00Z');const stamp=d=>d.toISOString().replace(/[-:]/g,'').slice(0,15)+'Z';let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Courtside//Prototype//EN','CALSCALE:GREGORIAN'];[0,1,2,4,5].forEach(i=>{let d=new Date(start);d.setUTCDate(d.getUTCDate()+i);d.setUTCHours(i===0?18:8,15);let end=new Date(d.getTime()+2*3600000);lines.push('BEGIN:VEVENT','UID:sample-'+i+'@courtside.prototype','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(d),'DTEND:'+stamp(end),'SUMMARY:DEMO - '+(i===0?'Welcome dinner with Katie + Eva':'Tennis with Katie + Eva'),'DESCRIPTION:Illustrative Courtside event only. No actual booking. UTC times reflect sample winter Spain schedule.','END:VEVENT')});lines.push('END:VCALENDAR');download('Courtside-sample-plans.ics',lines.join('\r\n'),'text/calendar');toast('Sample calendar downloaded. These are illustrative events.')}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function help(){go('help')}
function helpBody(){const rs=activeRequests();return `<div class="split"><div><section class="panel"><div class="eyebrow">PERSONAL CONCIERGE</div><h3>A question? A change?<br>Something you’d love to do?</h3><p class="muted small">Tell Courtside. We’ll check the options and ask for approval before confirming any extra cost.</p><div class="options">${[['stay','Change my stay'],['activity','Arrange an activity'],['transport','Arrival or transport'],['other','Something else']].map(x=>link('help/new/'+x[0],x[1]+' ↗','option')).join('')}</div></section><section class="panel"><div class="eyebrow">YOUR REQUESTS</div>${rs.length?rs.map(r=>`<div class="listrow"><div><strong>${esc(r.subject)}</strong><p class="small muted">${esc(r.type)} · ${r.history.length} updates</p></div><div>${statusBadge(r.status)}<br>${link('help/'+r.id,'Open request ↗','textlink')}</div></div>`).join(''):'<div class="empty"><h3>Nothing outstanding.</h3><p class="small">We’re here when you need us.</p></div>'}</section></div><aside><section class="panel"><div class="eyebrow">YOUR TRIP LEAD</div><h3>Someone accountable.</h3><p class="muted small">Jeffery · sample lead<br>Local support · to be assigned</p><div class="divider"></div><p class="small muted">During a live trip, urgent assistance would have a direct call or message channel. Staffed hours and escalation contacts would be provided before arrival.</p><button class="outline full" style="margin-top:20px" onclick="toast('Demo only: a staffed live contact channel would open here. No call or message is sent.')">Preview urgent contact ↗</button></section>${note()}</aside></div>`}
function helpPage(){ensureGroup();return shell('You’re taken<br>care of.','COURTSIDE CONCIERGE',`${rolebar()}${helpBody()}`,'Requests, decisions and confirmations, in one place.',link('trip-home','← My trip','textlink'))}
function newRequest(kind='other'){ensureGroup();const config={stay:['Stay change','An extra night in Spain','I’d like to stay one extra night after the group week. Please check the room and transfer options.'],activity:['Activity','A round of golf','I’d love to play golf on Tuesday afternoon. Please check options that fit around the shared tennis.'],transport:['Transport','A change to my arrival','Please help review my arrival and transfer arrangements.'],proposal:['Proposal question','A question about my proposal','I’d like to clarify my room arrangement before moving forward.'],other:['Other','A question for Courtside','']},c=config[kind]||config.other;return shell('Let us look<br>into it.','NEW CONCIERGE REQUEST',`<div class="focuslayout"><section class="panel"><div class="eyebrow">${esc(current().name)} · ${esc(c[0])}</div><form onsubmit="createRequest(event,'${esc(c[0])}')">${field('subject','What can we help with?',c[1],'text',true)}<label>A little more detail<textarea name="message" required>${esc(c[2])}</textarea></label>${kind==='activity'?`<label>Preferred timing${select('timing',['Tuesday afternoon','Wednesday','Help me decide'],'Tuesday afternoon')}</label>`:''}${note('This creates a request in the sample team queue. Nothing is booked, and no money is charged.')}<div class="actions"><button class="btn">Send demo request ↗</button>${link('help','Back','outline')}</div></form></section>${aside()}</div>`)}
function createRequest(e,type){e.preventDefault();const f=new FormData(e.target),id=uid('req'),p=current();state.requests.push({id,travelerId:p.id,type,subject:f.get('subject'),message:f.get('message'),timing:f.get('timing')||'',status:'Received',cost:0,offer:'',history:[{text:'Request received. Courtside will review the details.',time:stamp()}],owner:'Trip lead'});if(type==='Proposal question')p.proposal='Review requested';log(p.name+' requested: '+f.get('subject')+'.');persist();go('help/'+id)}
function requestDetail(id,team=false){ensureGroup();const r=state.requests.find(x=>x.id===id);if(!r)return shell('Request not found.','CONCIERGE',link(team?'operations':'help','Return ↗'));const p=findTraveler(r.travelerId);const body=`<div class="split"><section class="panel"><div class="row"><div><div class="eyebrow">${esc(p?.name)} · ${esc(r.type)}</div><h3>${esc(r.subject)}</h3></div>${statusBadge(r.status)}</div><div class="request-summary">${esc(r.message)}${r.timing?'<br>Preferred timing: '+esc(r.timing):''}</div>${r.offer?`<section class="offer"><div class="eyebrow">${r.status==='Unavailable'?'AN ALTERNATIVE TO CONSIDER':'YOUR OPTION'}</div><p class="small">${esc(r.offer)}</p><div class="row" style="margin-top:15px"><span class="price">$${Number(r.cost).toLocaleString()}</span><span class="small muted">Sample additional cost · not charged</span></div></section>`:''}${!team&&r.status==='Approval needed'?`<div class="actions"><button class="btn" onclick="approveRequest('${id}')">Approve this sample option ↗</button><button class="outline" onclick="declineRequest('${id}')">Decline option</button></div><p class="fieldhint">Approval returns this to Courtside for supplier confirmation. It does not charge a card.</p>`:''}${!team&&r.status==='Approved'?note('Your approval is saved. Courtside still needs to confirm the supplier and any related arrangements.'):''}${!team&&r.status==='Confirmed'?`<div class="actions"><button class="btn" onclick="tab='Arrangements';go('trip-home')">See updated arrangements ↗</button></div>`:''}${!team&&r.status==='Unavailable'?`<div class="actions">${link('help/new/other','Discuss an alternative ↗','btn')}</div>`:''}<div class="timeline">${r.history.map(h=>`<div class="timeline-item"><strong>${esc(h.text)}</strong><p>${esc(h.time)} · demo update</p></div>`).join('')}</div>${!['Confirmed','Declined','Canceled','Unavailable'].includes(r.status)&&!team?`<button class="plain danger" onclick="cancelRequest('${id}')">Cancel my request</button>`:''}</section><aside>${team?teamRequestActions(r):`<section class="panel"><div class="eyebrow">SEE THE WHOLE LOOP</div><h3>The work<br>behind your request.</h3><p class="muted small">Switch to Courtside to check options, prepare a quote and confirm it after guest approval.</p><div class="actions">${link('operations/request/'+id,'Preview team handling ↗','btn full')}</div></section>`}${note()}</aside></div>`;return shell(team?'Care, carried<br>through.':'Your request,<br>in good hands.',team?'TEAM · CONCIERGE REQUEST':'YOUR CONCIERGE REQUEST',body,'',link(team?'operations':'help','← Back','textlink'))}
function addHistory(r,text){r.history.push({text,time:stamp()});log(text);persist()}
function approveRequest(id){const r=state.requests.find(x=>x.id===id);r.status='Approved';addHistory(r,'Guest approved the sample option. Supplier confirmation needed.');render()}
function declineRequest(id){const r=state.requests.find(x=>x.id===id);r.status='Declined';addHistory(r,'Guest declined the sample option. Nothing booked.');render()}
function cancelRequest(id){const r=state.requests.find(x=>x.id===id);r.status='Canceled';addHistory(r,'Guest canceled the request.');render()}
function teamRequestActions(r){if(r.status==='Received')return `<section class="panel"><div class="eyebrow">NEXT ACTION · TRIP LEAD</div><h3>Check the options.</h3><p class="small muted">Review timing, supplier availability and related arrangements.</p><button class="btn full" style="margin-top:20px" onclick="state.requests.find(x=>x.id==='${r.id}').status='Checking options';addHistory(state.requests.find(x=>x.id==='${r.id}'),'Courtside is checking options.');render()">Start checking ↗</button></section>`;if(r.status==='Checking options')return `<section class="panel"><div class="eyebrow">PREPARE A SAMPLE OFFER</div><h3>A clear option.</h3><form onsubmit="offerRequest(event,'${r.id}')"><label>Option for the guest<textarea name="offer" required>${r.type==='Stay change'?'One additional Deluxe night, breakfast and an adjusted departure transfer. Sample supplier option; final availability requires confirmation.':r.type==='Activity'?'Tuesday golf at 14:30, after the morning tennis. Sample tee time and transportation to confirm.':'A sample option shaped around your request. Details and any cost require approval.'}</textarea></label>${field('cost','Additional sample cost',r.type==='Stay change'?'285':r.type==='Activity'?'175':'0','number',true)}<label>Timing / compatibility${select('compatible',['Fits the shared schedule','Needs a different time'],'Fits the shared schedule')}</label><button class="btn full" style="margin-top:20px">Send sample option ↗</button></form><button class="plain danger" style="margin-top:14px" onclick="unavailableRequest('${r.id}')">No availability · offer alternative</button></section>`;if(r.status==='Approved')return `<section class="panel"><div class="eyebrow">AFTER GUEST APPROVAL</div><h3>Close the loop.</h3><p class="small muted">Confirm the supplier, then update the traveler’s itinerary and related transport.</p><label class="option" style="margin-top:18px"><input type="checkbox" id="supplier-ok">Sample supplier checked</label><label class="option" style="margin-top:8px"><input type="checkbox" id="related-ok">Timing + related arrangements reviewed</label><button class="btn full" style="margin-top:20px" onclick="confirmRequest('${r.id}')">Confirm sample arrangement ↗</button></section>`;return `<section class="panel"><div class="eyebrow">CURRENT STATE</div><h3>${esc(r.status)}</h3><p class="small muted">${r.status==='Approval needed'?'The guest needs to review the option before Courtside can book it.':r.status==='Confirmed'?'The sample personal arrangements and cost summary are updated.':'This request has no active booking action.'}</p><div class="actions"><button class="btn full" onclick="state.active='${r.travelerId}';persist();go('help/${r.id}')">Preview guest’s view ↗</button></div></section>`}
function offerRequest(e,id){e.preventDefault();const f=new FormData(e.target),cost=Number(f.get('cost'));if(cost<0||!Number.isFinite(cost))return toast('Use a non-negative sample cost.');if(f.get('compatible')==='Needs a different time')return toast('Resolve the schedule conflict before sending an option.');const r=state.requests.find(x=>x.id===id);r.offer=f.get('offer');r.cost=cost;r.status='Approval needed';r.optionTime='14:30';addHistory(r,'Courtside prepared a sample option. Guest approval requested.');render()}
function unavailableRequest(id){const r=state.requests.find(x=>x.id===id);r.status='Unavailable';r.offer='The requested option is unavailable in this example. Courtside can explore a different day, room or activity before you decide.';r.cost=0;addHistory(r,'Requested option unavailable. An alternative discussion is offered.');render()}
function confirmRequest(id){if(!$('#supplier-ok')?.checked||!$('#related-ok')?.checked)return toast('Check the supplier and related arrangements before confirming.');const r=state.requests.find(x=>x.id===id);r.status='Confirmed';addHistory(r,'Sample supplier confirmed. Personal itinerary and arrangements updated.');render();toast('Sample arrangement confirmed and visible to the traveler.')}
function matchHome(){const m=state.match;if(!m)return shell('Find your<br>good company.','GROUP MATCHING',`<section class="panel"><p class="muted">Try a solo or small-party request to see the matching journey.</p><div class="actions">${link('request/match','Start a matching request ↗')}<button class="outline" onclick="sampleMatch()">Load a sample inquiry</button></div></section>`);return shell('A week worth<br>finding together.','YOUR GROUP REQUEST · '+esc(m.id),`<div class="split"><section class="panel"><div class="row"><h3>${esc(m.name.split(' ')[0])}’s request.</h3>${statusBadge(m.status)}</div><div class="review"><div class="row"><span>Possible dates</span><span>${esc(m.weeks.join(', '))}</span></div><div class="row"><span>Party</span><span>${esc(m.party)}</span></div><div class="row"><span>Tennis</span><span>${esc(m.level)} · ${esc(m.tennis)}</span></div><div class="row"><span>Contact</span><span>${esc(m.email)}</span></div></div>${m.proposedDate?`<section class="offer"><div class="eyebrow">A POSSIBLE WEEK</div><h3>${esc(m.proposedDate)}, 2027</h3><p class="small muted">Example group: social, balanced tennis, with time for independent afternoons. No private traveler information is shared.</p><p class="small">Illustrative shared-room base: $${m.proposalPrice.toLocaleString()} per player. Final party and partner costs require a personal proposal.</p><div class="actions"><button class="btn" onclick="acceptMatch()">Explore this proposed week ↗</button><button class="outline" onclick="updateMatchModal()">Discuss another week</button></div></section>`:`<p class="muted small">${m.status==='Withdrawn'?'Your interest has been withdrawn. You can submit a new request if plans change.':m.status==='No suitable week yet'?'We haven’t found a suitable departure in this example. Update your dates, ask a question or stay in touch.':'Courtside reviews dates, tennis preferences and possible groups personally. We’ll propose a specific week before you make a commitment.'}</p>`}<div class="actions">${m.status!=='Withdrawn'?`<button class="outline" onclick="updateMatchModal()">Update my request</button><button class="back" onclick="withdrawMatch()">Withdraw interest</button>`:link('start','Start again ↗','outline')}${link('operations','Preview team matching ↗','textlink')}</div><div class="timeline">${m.history.map(h=>`<div class="timeline-item"><strong>${esc(h.text)}</strong><p>${esc(h.time)} · sample update</p></div>`).join('')}</div></section>${supportPanel()}</div>`,'A request starts a conversation. It does not guarantee a matched departure.')}
function sampleMatch(){state.match={id:'CS-MATCH-001',name:'Riley Example',email:'riley@example.com',weeks:['Feb 7–13','Feb 14–20'],party:'Solo',level:'3.5',tennis:'Four mornings',notes:'Social tennis and plenty of time to explore.',status:'Reviewing possible weeks',proposedDate:'',proposalPrice:2995,history:[{text:'Sample matching inquiry received.',time:stamp()}]};persist();go('match-home')}
function updateMatchModal(){const m=state.match;modal('Update matching request',`<div class="eyebrow">KEEP YOUR OPTIONS CURRENT</div><h2>What works<br>for you?</h2><form onsubmit="saveMatchUpdate(event)"><label>Possible week${select('date',['Flexible',...dates.slice(1)],m.weeks[0])}</label><label>Anything to add?<textarea name="notes">${esc(m.notes)}</textarea></label><button class="btn full">Save request update ↗</button></form>`)}
function saveMatchUpdate(e){e.preventDefault();const f=new FormData(e.target),m=state.match;m.weeks=[f.get('date')];m.notes=f.get('notes');m.proposedDate='';m.status='Reviewing updated dates';m.history.push({text:'Traveler updated preferences. Courtside review needed.',time:stamp()});log('Matching traveler updated their request.');persist();closeModal();render()}
function withdrawMatch(){if(!confirm('Withdraw this sample matching inquiry?'))return;state.match.status='Withdrawn';state.match.proposedDate='';state.match.history.push({text:'Traveler withdrew interest.',time:stamp()});persist();render()}
function proposeMatch(e){e.preventDefault();const f=new FormData(e.target),m=state.match;if(!m)return;m.proposedDate=f.get('date');m.status='Week proposed';m.history.push({text:'Courtside proposed '+m.proposedDate+'. Traveler review needed.',time:stamp()});log('Specific week proposed for '+m.name+'.');persist();render()}
function acceptMatch(){const m=state.match;ensureGroup();const id='matched-riley';let p=state.matchTraveler;if(!p){p={id,name:m.name,email:m.email,role:'Player',invited:true,participation:'Interested',complete:false,room:'Help me decide',tennis:m.tennis,level:m.level,interests:[],proposal:'Sent',payment:'Not due',matchedDate:m.proposedDate,matchParty:m.party};state.matchTraveler=p}p.matchedDate=m.proposedDate;state.active=id;m.status='Reviewing personal proposal';persist();go('proposal');toast('This demo traveler can now review a personal proposal. No booking is made.')}
function hostDesk(){ensureGroup();const g=state.group,count=g.attendees.filter(p=>!p.removed&&p.participation==='Interested').length,confirmed=g.attendees.filter(p=>!p.removed&&p.proposal==='Confirmed').length;let body='';if(hostTab==='Brief')body=hostBrief();else if(hostTab==='Compensation')body=hostCompensation();else body=`<div class="statgrid"><div class="stat"><strong>${g.attendees.filter(p=>!p.removed).length}</strong><span>People in planning</span></div><div class="stat"><strong>${count}</strong><span>Interested travelers</span></div><div class="stat"><strong>${confirmed}</strong><span>Sample confirmed</span></div></div><div class="split"><div><section class="panel"><div class="eyebrow">YOUR NEXT SPAIN WEEK</div>${tripmini()}<div class="divider"></div><div class="task"><div><strong>Your invitation</strong><p>Ready-to-share words, link and code.</p></div><button class="soft mini" onclick="hostInvitation()">Open ↗</button></div><div class="task"><div><strong>Your hosting brief</strong><p>Shared tennis, meals and protected free time.</p></div><button class="soft mini" onclick="hostTab='Brief';render()">Review ↗</button></div><div class="task"><div><strong>Your compensation</strong><p>Private agreement and sample payment status.</p></div><button class="soft mini" onclick="hostTab='Compensation';render()">View ↗</button></div><div class="task"><div><strong>Courtside is coordinating</strong><p>Travelers, rooms, transfers, suppliers and personal requests.</p></div>${badge('With our team')}</div></section><section class="panel"><div class="eyebrow">YOUR ROLE / OUR RESPONSIBILITY</div><h3>Be present.<br>We’ll handle the rest.</h3><div class="includes"><div>Your agreed tennis + hosting</div><div>Our supplier coordination</div><div>Your community connection</div><div>Our guest follow-up</div><div>Your protected free time</div><div>Our trip support</div></div></section></div>${supportPanel()}</div>`;return shell('More hosting.<br>Less handling.','HOST HOME · KATIE’S SAMPLE VIEW',`<div class="accountbar"><span>Your experiences</span><label style="margin:0;font-size:0">Select host experience<select aria-label="Select host experience" onchange="state.hostTrip=this.value;persist();render()"><option value="spain" ${state.hostTrip==='spain'?'selected':''}>The Spanish Offseason</option><option value="idea" ${state.hostTrip==='idea'?'selected':''}>Your next trip · idea</option></select></label></div>${state.hostTrip==='idea'?hostIdea():`<nav class="tabs">${['Overview','Brief','Compensation'].map(t=>`<button class="${hostTab===t?'selected':''}" onclick="hostTab='${t}';render()">${t}</button>`).join('')}</nav>${body}`}`,'Your community brings the connection. Courtside takes care of the journey.',link('host','View public host page ↗','textlink'))}
function hostBrief(){return `<div class="split"><section class="panel"><div class="eyebrow">HOSTING BRIEF · ${esc(groupDate())}, 2027</div><div class="row"><h3>Your week,<br>clearly laid out.</h3>${statusBadge(state.hostApproved?'Sample agreed':'Review needed')}</div><p class="muted small">Example commitments, not a live host agreement. Final dates, staffing and compensation require agreement before a real trip launches.</p><div class="day"><span>SUNDAY</span><div><strong>Welcome dinner</strong><br>Join the table and help everyone settle in.</div></div><div class="day"><span>MON / TUE<br>THU / FRI</span><div><strong>Four tennis mornings</strong><br>Example coaching and match-play program with Katie + Eva.</div></div><div class="day"><span>FRIDAY</span><div><strong>Farewell dinner</strong><br>One last evening with the group.</div></div><div class="day"><span>FREE TIME</span><div><strong>Wednesday + unscheduled afternoons</strong><br>Protected time. Individual guest activities are coordinated by Courtside.</div></div><div class="actions"><button class="btn" onclick="state.hostApproved=true;log('Host acknowledged the sample hosting brief.');persist();render();toast('Sample brief acknowledged. No legal agreement is accepted.')">${state.hostApproved?'Brief acknowledged ✓':'Acknowledge sample brief ↗'}</button><button class="outline" onclick="hostQuestion()">Discuss a change</button></div></section><aside><section class="panel"><div class="eyebrow">RELEVANT GUEST CONTEXT</div><h3>Your people.</h3>${state.group.attendees.filter(p=>!p.removed&&p.participation==='Interested').map(p=>`<div class="listrow"><span>${esc(p.name)}<br><span class="muted">${esc(p.role)} · Tennis: ${esc(p.level||'to discuss')}</span></span></div>`).join('')}<p class="fieldhint">Private care notes, personal appointments and individual costs are not part of this brief.</p></section><section class="panel"><div class="eyebrow">HAND IT TO COURTSIDE</div><p class="muted small">Guest transport, rooms, supplier changes and coordination stay with the trip team.</p><button class="outline full" onclick="hostQuestion()">Contact the trip lead ↗</button></section></aside></div>`}
function hostCompensation(){return `<div class="split"><section class="panel"><div class="eyebrow">YOUR PRIVATE HOST AGREEMENT</div><h3>Clear before<br>you say yes.</h3><div class="review"><div class="row"><span>Hosting compensation</span><span>To agree</span></div><div class="row"><span>What it covers</span><span>Agreed sessions, meals and hosting commitments</span></div><div class="row"><span>Travel + accommodation</span><span>Responsibility to establish</span></div><div class="row"><span>Payment timing</span><span>To agree before launch</span></div><div class="row"><span>Sample status</span>${statusBadge(state.hostPaid?'Sample payout recorded':'Terms not established')}</div></div>${note('Commercial terms are intentionally unconfirmed. A live host would see their agreed amounts, conditions and payment status here. No payment is made.')}<button class="outline" onclick="hostQuestion()">Discuss my host offer ↗</button></section>${supportPanel()}</div>`}
function hostInvitation(){const message='I’m taking a small group to Spain with Courtside. Six nights, tennis with Eva and me, and time to enjoy the Costa Blanca together. I’d love you to join us.\n\n'+location.href.split('#')[0]+'#/trip';modal('Host invitation',`<div class="eyebrow">READY TO SHARE</div><h2>A personal<br>invitation.</h2><p class="muted small">Suggested copy for Katie to review and make her own.</p><textarea id="host-message" style="height:190px">${esc(message)}</textarea><div class="review"><div class="row"><span>Sample invitation code</span><strong>JEFF</strong></div></div><button class="btn full" onclick="copyText($('#host-message').value,'Invitation copied. You choose who to send it to.')">Copy invitation ↗</button>`)}
function hostIdea(){return `<div class="split"><section class="panel"><div class="eyebrow">YOUR NEXT EXPERIENCE</div><h3>Where would you<br>love to take them?</h3><p class="muted small">A destination, a club or the beginning of an idea. Courtside will help shape a workable trip.</p><form onsubmit="saveHostIdea(event)">${field('destination','Where do you have in mind?','','text',true,'A place you’d love to share')}${field('window','When might it work?','','text',true,'A month or travel window')}${field('people','Approximate community size','','text',true,'A small group, a whole club, or not sure yet')}<label>What would make it special?<textarea name="story" required></textarea></label><button class="btn" style="margin-top:20px">Share a demo trip idea ↗</button></form>${state.hostIdeas.length?`<div class="divider"></div><h3>Your ideas with Courtside</h3>${state.hostIdeas.map(i=>`<div class="listrow"><span>${esc(i.destination)}<br><span class="muted">${esc(i.window)}</span></span>${badge('Conversation needed','warn')}</div>`).join('')}`:''}</section>${supportPanel()}</div>`}
function saveHostIdea(e){e.preventDefault();state.hostIdeas.push(Object.fromEntries(new FormData(e.target)));log('Host submitted a sample trip idea.');persist();render();toast('Trip idea saved for the Courtside team.')}
function hostQuestion(){modal('Contact trip lead',`<div class="eyebrow">HOST SUPPORT</div><h2>We’re on it.</h2><form onsubmit="event.preventDefault();state.tasks.push({id:uid('task'),kind:'host',title:'Follow up with host: '+this.elements.message.value,owner:'Trip lead',due:'Next working session',done:false});log('Host asked the trip lead a question.');persist();closeModal();toast('Sample host question added to the team queue.')"><label>What would you like to discuss?<textarea name="message" required placeholder="A schedule change, hosting question or next-trip idea."></textarea></label><button class="btn full" style="margin-top:20px">Send demo question ↗</button></form>${note()}`)}
function application(){return `<div class="flow"><div class="flow-main"><div class="eyebrow">HOST WITH COURTSIDE</div><h1>Bring your people.<br>Enjoy the journey.</h1><p class="muted">Tell us about yourself and the experience you imagine. We follow up with a conversation.</p><form onsubmit="saveApplication(event)">${field('name','Your name','','text',true,'A sample applicant')}${field('email','Email','','email',true,'pro@example.com')}${field('club','Where do you coach?','','text',true,'Club, city and country')}${field('referral','Were you introduced by someone? · optional','','text',false,'Katie or another Courtside host')}<label>Your professional background<textarea name="background" required></textarea></label><label>Tell us about your community<textarea name="community" required></textarea></label>${field('destination','Where would you love to take them?','','text',true)}${note('Use sample information. This demo application is stored in this browser, with no real submission.')}<button class="btn full" style="margin-top:20px">Send demo application ↗</button></form></div><aside class="flow-aside panel"><div class="eyebrow">OUR HOST STANDARD</div><h3>Exceptional teachers.<br>Thoughtful hosts.</h3><p class="small muted">Teaching, warmth, professionalism, reliability and a real connection to a community.</p><div class="divider"></div><p class="small muted">Katie helps lead selection. Acceptance as a host begins the relationship; every trip gets its own plan and approval.</p></aside></div>`}
function saveApplication(e){e.preventDefault();state.applications.push({id:uid('app'),...Object.fromEntries(new FormData(e.target)),status:'Application received'});log('New sample host application received.');persist();go('application-done')}
function applicationDone(){return `<section class="success"><div class="center"><div class="successmark">✓</div><div class="eyebrow">DEMO APPLICATION SAVED</div><h1>Good people.<br>Great possibilities.</h1><p class="muted">In the live service, Katie and Courtside would review your application and arrange a conversation. No application has been sent.</p><div class="actions">${link('host-desk','Preview an accepted host ↗')}${link('operations','See the team review','outline')}</div></div></section>`}
function operations(){ensureGroup();const g=state.group,newRequests=state.requests.filter(r=>!['Confirmed','Declined','Canceled','Unavailable'].includes(r.status)).length;const body=`${note('Sample operations workspace. Guest actions in this browser update these records. All suppliers, costs and booking states are illustrative.')}<nav class="tabs" aria-label="Team workspace">${['Attention','Group & guests','Readiness','Concierge','Hosts','Economics'].map(t=>`<button class="${teamTab===t?'selected':''}" onclick="teamTab='${t}';render()">${t}</button>`).join('')}</nav>${teamTab==='Attention'?teamAttention():teamTab==='Group & guests'?teamGroup():teamTab==='Readiness'?teamReadiness():teamTab==='Concierge'?teamConcierge():teamTab==='Hosts'?teamHosts():teamEconomics()}`;return shell('The care<br>behind the week.','COURTSIDE TEAM · SPAIN',body,'One accountable trip lead. Every next action visible.',`<span class="badge">${newRequests} open concierge requests</span>`)}
function teamAttention(){const g=state.group,follow=g.attendees.filter(p=>!p.removed&&p.participation!=='Not attending'&&(!p.complete||!p.invited)),pending=state.requests.filter(r=>!['Confirmed','Declined','Canceled','Unavailable'].includes(r.status)),tasks=state.tasks.filter(t=>!t.done);return `<div class="statgrid stats4"><div class="stat"><strong>${g.reviewed?'0':'1'}</strong><span>Group inquiry to review</span></div><div class="stat"><strong>${follow.length}</strong><span>Traveler follow-ups</span></div><div class="stat"><strong>${pending.length}</strong><span>Concierge requests</span></div><div class="stat"><strong>${state.suppliers.filter(s=>s.status!=='Confirmed').length}</strong><span>Supplier checks</span></div></div><div class="split"><div><section class="panel"><div class="eyebrow">WHAT NEEDS ATTENTION</div><h3>The next useful action.</h3>${!g.reviewed?`<div class="actioncard"><div class="row"><div><h4>Review ${esc(g.name)}</h4><p>${esc(g.weeks.join(', '))} · ${esc(g.players)} players · partners ${esc(g.partners)}</p><p>Owner: Trip lead · Due: next working session</p></div><button class="soft mini" onclick="gReview()">Start review ↗</button></div></div>`:''}${g.changeReview?`<div class="actioncard"><h4>Group preferences changed</h4><p>Review dates, tennis and payment responsibility before updating arrangements.</p><button class="plain" onclick="state.group.changeReview=false;log('Group preference change reviewed.');persist();render()">Mark reviewed</button></div>`:''}${pending.map(r=>`<div class="actioncard"><div class="row"><div><h4>${esc(r.subject)}</h4><p>${esc(findTraveler(r.travelerId)?.name)} · ${esc(r.status)}</p><p>Owner: ${esc(r.owner)} · Next: ${r.status==='Received'?'check options':r.status==='Approved'?'confirm supplier':r.status==='Approval needed'?'await guest decision':'prepare option'}</p></div>${link('operations/request/'+r.id,'Open ↗','soft mini')}</div></div>`).join('')}${tasks.map(t=>`<div class="actioncard"><h4>${esc(t.title)}</h4><p>Owner: ${esc(t.owner)} · Due: ${esc(t.due)}</p><button class="plain" onclick="completeTask('${t.id}')">Mark sample task complete</button></div>`).join('')}${!pending.length&&!tasks.length&&g.reviewed&&!g.changeReview?'<p class="muted small">No new urgent actions. Check traveler follow-ups and readiness before committing arrangements.</p>':''}</section><section class="panel"><div class="eyebrow">ACTIVITY</div>${state.activity.length?state.activity.slice(0,7).map(a=>`<div class="listrow"><span>${esc(a.text)}</span><span class="muted">${esc(a.time)}</span></div>`).join(''):'<p class="muted small">Actions from the walkthrough appear here.</p>'}</section></div><aside><section class="panel"><div class="eyebrow">DEPARTURE SUMMARY</div>${tripmini()}${progress(g.stage)}<p class="small muted">Trip lead: Jeffery · sample assignment<br>Host: Katie + Eva<br>Local support: to be assigned</p><div class="actions"><button class="btn full" onclick="teamTab='Readiness';render()">Review departure readiness ↗</button></div></section><section class="panel"><div class="eyebrow">GROUP MATCHING</div>${state.match?`<h3>${esc(state.match.name)}</h3><p class="small muted">${esc(state.match.status)}</p><button class="plain" onclick="teamTab='Group & guests';render()">Review matching inquiry ↗</button>`:`<h3>Room for the right fit.</h3><p class="small muted">No matching inquiry in this browser yet.</p><button class="plain" onclick="sampleMatch();teamTab='Group & guests';go('operations')">Load sample matching inquiry ↗</button>`}</section></aside></div>`}
function gReview(){state.group.reviewed=true;if(state.group.stage==='Inquiry')state.group.stage='Planning';log('Trip lead began reviewing the private group inquiry.');persist();teamTab='Group & guests';render()}
function completeTask(id){const t=state.tasks.find(t=>t.id===id);if(t)t.done=true;log('Sample follow-up completed.');persist();render()}
function teamGroup(){const g=state.group,people=g.attendees.filter(p=>!p.removed);return `<section class="panel"><div class="panelhead"><div><div class="eyebrow">PRIVATE GROUP · ${esc(g.id)}</div><h3>${esc(g.name)}</h3></div>${statusBadge(g.stage)}</div><p class="small muted">Organizer: ${esc(g.organizerName)} · ${esc(g.organizerEmail)}<br>Requested: ${esc(g.weeks.join(', '))} · ${esc(g.tennis)}</p><div class="tablewrap"><table><thead><tr><th>Traveler</th><th>Participation</th><th>Planning / follow-up</th><th>Proposal</th><th>Action</th></tr></thead><tbody>${people.map(p=>`<tr><td>${esc(p.name)}<br><span class="muted">${esc(p.role)}</span></td><td>${esc(p.participation)}</td><td>${p.complete?'Details complete':!p.invited?'Invitation needed':'Personal details needed'}${p.arrival?'<br>Arrival saved':''}</td><td>${esc(p.proposal||'Draft')}</td><td><button class="plain" onclick="teamTraveler('${p.id}')">Open record ↗</button></td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="btn" onclick="sendProposals()">Send sample proposals ↗</button>${link('group','Preview organizer view','outline')}<button class="outline" onclick="teamTab='Readiness';render()">Check availability</button></div><p class="fieldhint">Sample proposals are sent to interested travelers only. Missing individual details are flagged; no real messages are sent.</p></section>${state.match?teamMatching():`<section class="panel"><div class="eyebrow">SOLO / SMALL-PARTY INQUIRIES</div><p class="muted small">No matching inquiry in this browser.</p><button class="plain" onclick="sampleMatch();teamTab='Group & guests';go('operations')">Load a sample matching request ↗</button></section>`}`}
function teamTraveler(id){const p=state.group.attendees.find(p=>p.id===id);modal('Private traveler record',`<div class="eyebrow">TEAM · PRIVATE TRAVELER RECORD</div><h2>${esc(p.name)}</h2><div class="review"><div class="row"><span>Contact</span><span>${esc(p.email||'Not supplied')}</span></div><div class="row"><span>Room preference</span><span>${esc(p.room)}<br>Roommate: ${esc(p.roommate||'to discuss')}</span></div><div class="row"><span>Tennis</span><span>${esc(p.level||'Not sure yet')} · ${esc(p.tennis)}</span></div><div class="row"><span>Interests</span><span>${esc(p.interests?.join(', ')||'Not supplied')}</span></div><div class="row"><span>Private care notes</span><span>${esc(p.care||'None supplied')}</span></div><div class="row"><span>Arrival</span><span>${p.arrival?esc(p.arrival.flight)+' '+esc(p.arrival.date)+' '+esc(p.arrival.time):'Not supplied'}</span></div></div><div class="actions"><button class="btn" onclick="addTravelerFollowup('${id}')">Add follow-up</button><button class="outline" onclick="state.active='${id}';persist();closeModal();go('preferences')">Preview traveler</button></div>`)}
function addTravelerFollowup(id){const p=state.group.attendees.find(x=>x.id===id);if(state.tasks.some(t=>!t.done&&t.kind==='traveler'&&t.travelerId===id))return toast('An open follow-up already exists for this traveler.');state.tasks.push({id:uid('task'),kind:'traveler',travelerId:id,title:'Follow up directly with '+p.name+' about outstanding planning details',owner:'Trip lead',due:'Next working session',done:false});log('Personal follow-up assigned for '+p.name+'.');persist();closeModal();toast('Traveler follow-up added to Attention.')}
function sendProposals(){const eligible=state.group.attendees.filter(p=>!p.removed&&p.participation==='Interested');if(!eligible.length)return toast('An interested traveler is needed first.');modal('Send sample proposals',`<div class="eyebrow">REVIEW BEFORE SENDING</div><h2>A clear next step.</h2><p class="muted small">Prepare sample personal proposals for ${eligible.length} interested traveler${eligible.length===1?'':'s'}. Existing confirmed travelers stay confirmed.</p><label>Proposed departure${select('date',dates.slice(1),groupDate())}</label><div class="alert">${eligible.filter(p=>!p.complete).length} traveler(s) still have planning details outstanding. This demo can show a draft proposal, but final pricing and arrangements require those details.</div>${note('No email is sent. Sample proposals will appear in each traveler’s view. Supplier availability and commercial terms remain unverified.')}<button class="btn full" onclick="finishSendProposals(this.previousElementSibling?.value)">Send demo proposals ↗</button>`)}
function finishSendProposals(){const date=$('#overlay select').value;state.group.chosenDate=date;state.group.stage='Proposal';state.group.attendees.filter(p=>!p.removed&&p.participation==='Interested'&&p.proposal!=='Confirmed').forEach(p=>p.proposal='Sent');log('Sample personal proposals prepared for '+date+'.');persist();closeModal();render();toast('Sample proposals available in traveler views.')}
function teamMatching(){const m=state.match;return `<section class="panel"><div class="eyebrow">GROUP-MATCHING INQUIRY · ${esc(m.id)}</div><div class="row"><h3>${esc(m.name)}</h3>${statusBadge(m.status)}</div><p class="small muted">${esc(m.party)} · Tennis ${esc(m.level)} · ${esc(m.tennis)}<br>Possible dates: ${esc(m.weeks.join(', '))}</p><p class="small muted">${esc(m.notes||'No additional notes.')}</p>${m.status==='Withdrawn'?'<p class="notice">Traveler withdrew interest. No follow-up proposal should be sent.</p>':`<form onsubmit="proposeMatch(event)"><label>Suggest a specific departure${select('date',dates.slice(1),m.weeks.find(w=>w!=='Flexible')||'Feb 7–13')}</label><div class="actions"><button class="btn">Propose sample week ↗</button><button class="outline" type="button" onclick="state.match.status='No suitable week yet';state.match.proposedDate='';state.match.history.push({text:'No suitable week yet. Alternative dates can be discussed.',time:stamp()});persist();render()">No suitable week yet</button>${link('match-home','Preview traveler status ↗','textlink')}</div></form>`}</section>`}
function teamReadiness(){const g=state.group;return `<div class="split"><section class="panel"><div class="eyebrow">SUPPLIERS + COMMITMENTS</div><h3>Before we make promises.</h3><p class="small muted">A room quote is different from a confirmed stay. Every dependency needs an owner and a record.</p><div class="suppliers">${state.suppliers.map(s=>`<div class="supplierrow"><div><strong>${s.title}</strong> <button class="plain" onclick="supplierDetails('${s.id}')">Details ↗</button><small>${s.detail}</small></div><div class="supplier-meta">Owner: ${esc(s.owner||'Trip lead')}<br>${s.deadline?'Due: '+esc(s.deadline)+'<br>':''}Next: ${s.status==='Confirmed'?'retain sample confirmation':s.status==='Held'?'review hold deadline':s.status==='Quoted'?'review quote + availability':'follow up with supplier'}</div>${select('supplier-'+s.id,['To request','Requested','Quoted','Held','Confirmed'],s.status,`aria-label="${s.title} status" onchange="supplierStatus('${s.id}',this.value)"`)}</div>`).join('')}</div><div class="task"><div><strong>Host commitments</strong><p>Schedule, free time and compensation require agreement.</p></div>${statusBadge(state.hostApproved?'Sample brief acknowledged':'Review needed')}</div><div class="task"><div><strong>Guest commercial terms</strong><p>Complete pricing, payment schedule and cancellation terms.</p></div>${badge('To establish','warn')}</div><div class="task"><div><strong>Service capacity</strong><p>Local lead, remote support and escalation coverage.</p></div>${badge('Staffing to confirm','warn')}</div><p class="fieldhint">Changing a supplier status is a local simulation. Actual confirmation references and hold deadlines would be recorded in the live operation.</p></section><aside><section class="panel"><div class="eyebrow">READINESS SNAPSHOT</div><h3>${state.suppliers.filter(s=>s.status==='Confirmed').length} of 4<br>supplier checks.</h3><p class="muted small">${g.attendees.filter(p=>p.proposal==='Confirmed'&&!p.removed).length} sample confirmed travelers.<br>${g.attendees.filter(p=>!p.complete&&!p.removed&&p.participation!=='Not attending').length} travelers with planning outstanding.</p><div class="divider"></div><p class="small muted">This prototype intentionally keeps commercial and service commitments marked as unresolved. It is not a launch authorization.</p></section></aside></div>`}
function supplierStatus(id,value){state.suppliers.find(s=>s.id===id).status=value;log('Sample supplier '+id+' status: '+value+'.');persist();render()}
function teamConcierge(){return `<section class="panel"><div class="eyebrow">PERSONAL REQUESTS</div><h3>Every request has an owner.</h3>${state.requests.length?state.requests.map(r=>`<div class="listrow"><div><strong>${esc(r.subject)}</strong><p class="muted small">${esc(findTraveler(r.travelerId)?.name)} · Owner: ${esc(r.owner)}<br>Next: ${r.status==='Received'?'Check the options':r.status==='Checking options'?'Prepare a proposal':r.status==='Approval needed'?'Await guest approval':r.status==='Approved'?'Confirm supplier + related arrangements':'No open booking action'}</p></div><div>${statusBadge(r.status)}<br>${link('operations/request/'+r.id,'Handle request ↗','textlink')}</div></div>`).join(''):`<div class="empty"><h3>A quiet queue.</h3><p class="small">Try requesting an extra night from a traveler’s view.</p><div class="actions">${link('help/new/stay','Create a sample request ↗')}</div></div>`}</section>`}
function teamHosts(){return `<div class="split"><div><section class="panel"><div class="eyebrow">HOST COMMUNITY</div><h3>Selected with care.</h3>${state.applications.length?state.applications.map(a=>`<div class="actioncard"><div class="row"><div><h4>${esc(a.name)}</h4><p>${esc(a.club)} · Referral: ${esc(a.referral||'None supplied')}</p><p>Community: ${esc(a.community)}</p><p>Trip idea: ${esc(a.destination)}</p></div>${statusBadge(a.status)}</div><div class="actions"><button class="soft mini" onclick="applicationStage('${a.id}','Conversation requested')">Request conversation</button><button class="outline mini" onclick="applicationStage('${a.id}','Sample selected host')">Mark sample selected</button></div></div>`).join(''):'<p class="muted small">No host applications in this browser. Submit a sample application to see it here.</p>'}<div class="actions">${link('application','Preview application ↗','textlink')}</div></section><section class="panel"><div class="eyebrow">NEXT-TRIP IDEAS</div>${state.hostIdeas.length?state.hostIdeas.map(i=>`<div class="listrow"><span>${esc(i.destination)}<br><span class="muted">${esc(i.window)} · ${esc(i.people)}</span></span>${badge('Conversation needed','warn')}</div>`).join(''):'<p class="muted small">Host ideas appear here when submitted from their trip selector.</p>'}</section></div><aside><section class="panel"><div class="eyebrow">CURRENT HOST</div><h3>Katie + Eva</h3><div class="task"><span>Hosting brief</span>${statusBadge(state.hostApproved?'Sample acknowledged':'To agree')}</div><div class="task"><span>Compensation</span>${badge('Terms to establish','warn')}</div><button class="outline full" style="margin-top:20px" onclick="hostTab='Brief';go('host-desk')">Preview host brief ↗</button></section></aside></div>`}
function applicationStage(id,value){state.applications.find(a=>a.id===id).status=value;log('Sample host application moved to '+value+'.');persist();render()}
function teamEconomics(){const people=state.group.attendees.filter(p=>!p.removed&&p.participation==='Interested'),rev=people.reduce((a,p)=>a+priceFor(p),0),extras=state.requests.filter(r=>r.status==='Confirmed').reduce((a,r)=>a+Number(r.cost),0);return `<div class="split"><section class="panel"><div class="eyebrow">ILLUSTRATIVE REVENUE BRIDGE</div><h3>Price the whole service.</h3><div class="review"><div class="row"><span>Interested travelers · base example</span><strong>$${rev.toLocaleString()}</strong></div><div class="row"><span>Sample confirmed extras</span><strong>$${extras.toLocaleString()}</strong></div><div class="row"><span>Illustrative potential revenue</span><strong>$${(rev+extras).toLocaleString()}</strong></div></div><p class="small muted">This includes interested travelers, not verified booked revenue. Base assumptions are $2,995 per player and $1,995 per non-playing partner. Room changes and party-specific quotes are not included.</p><div class="listrow"><span>Accommodation + travel suppliers</span>${badge('Actual quotes needed','warn')}</div><div class="listrow"><span>Host compensation</span>${badge('To agree','warn')}</div><div class="listrow"><span>Local + remote support</span>${badge('Budget needed','warn')}</div><div class="listrow"><span>Coordination + exceptions</span>${badge('Measure actual time','warn')}</div><div class="listrow"><span>Company contribution</span><strong>Not established</strong></div>${note('Revenue is not profit. Supplier costs, host compensation, support and contingency must be established before a contribution forecast is meaningful.')}</section><aside><section class="panel"><div class="eyebrow">LEARN FROM THE FIRST TRIPS</div><h3>The work<br>behind the week.</h3><form onsubmit="event.preventDefault();state.coordinationHours=Number(this.elements.hours.value);persist();toast('Sample coordination hours saved.')"><label>Recorded coordination hours<input type="number" name="hours" min="0" step="0.5" value="${Number(state.coordinationHours||0)}"></label><button class="outline full" style="margin-top:20px">Save sample hours</button></form><p class="small muted">Track recurring tasks, exceptions and times the host had to step into operations. Use that evidence to plan staffing and automation.</p></section><section class="panel"><div class="eyebrow">POST-TRIP REVIEW</div><h3>What guests told us.</h3>${state.group.attendees.filter(p=>p.feedback).map(p=>`<div class="listrow"><div><strong>${esc(p.name)}</strong><p class="small muted">Care: ${esc(p.feedback.careRating)} · Travel again: ${esc(p.feedback.again)}<br>${esc(p.feedback.message)}</p></div></div>`).join('')||'<p class="small muted">Sample guest feedback appears here after the After the trip view.</p>'}</section></aside></div>`}
function invite(){return `<section class="success"><div class="center" style="max-width:470px"><div class="eyebrow">YOU’RE INVITED</div><h1>A week<br>with your pro.</h1><p class="muted">Enter the code from your invitation to explore the experience.</p><form onsubmit="event.preventDefault();if(this.elements.code.value.trim().toUpperCase()==='JEFF')go('trip');else go('invite-unavailable')">${field('code','Invitation code','','text',true,'JEFF')}<button class="btn full" style="margin-top:20px">Open my invitation ↗</button></form><p class="small muted">Sample code: JEFF · for this walkthrough only</p><div class="divider"></div>${link('waitlist','No invitation? Request one here ↗','textlink')}</div></section>`}
function unavailableInvite(){return shell('Let’s find<br>your invitation.','INVITATION NOT RECOGNIZED',`<section class="panel"><p class="muted">That sample code isn’t recognized. Try JEFF, or register interest and Courtside can help in the live service.</p><div class="actions">${link('invite','Try again ↗')}${link('waitlist','Request an invitation','outline')}</div></section>`)}
function waitlist(){return `<section class="success"><div class="center" style="max-width:490px"><div class="eyebrow">YOUR NEXT INVITATION</div><h1>Something good<br>to look forward to.</h1><p class="muted">Spain now, a future destination or a favorite host’s next journey.</p><form style="text-align:left" onsubmit="event.preventDefault();state.waitlisted=true;persist();go('waitlist-done')">${field('name','Your name · optional')}${field('email','Your email','','email',true,'you@example.com')}<label>I’m interested in${select('interest',['Spain with Katie + Eva','Katie’s future trips','Future Courtside experiences','Mallorca · future idea','Charleston · future idea'],'Spain with Katie + Eva')}</label><button class="btn full" style="margin-top:20px">Save demo interest ↗</button>${note('Nothing is sent or subscribed. Use a sample email for this walkthrough.')}</form></div></section>`}
function waitlistDone(){return `<section class="success"><div class="center"><div class="successmark">✓</div><div class="eyebrow">DEMO INTEREST SAVED</div><h1>Anticipation<br>looks good on you.</h1><p class="muted">In the live experience, Courtside would follow up about the trips you chose. Nothing has been sent or subscribed in this demo.</p><div class="actions">${link('trip','Explore Spain ↗')}${link('','Home','outline')}</div></div></section>`}
function guide(){return shell('One trip.<br>Every perspective.','CONCEPT 02 · WALKTHROUGH',`<p class="muted" style="max-width:700px">Follow a group from the first inquiry to individual planning, a proposal, a personal itinerary and a concierge request. The same sample records connect guests, hosts and Courtside.</p><div class="callout" style="margin-top:30px"><div class="eyebrow">THE QUICKEST WAY TO EXPLORE</div><h3>Meet Alex’s Spain group.</h3><p>Six players, two possible partners and different ideas of a perfect afternoon. Load their story to explore the connected experience.</p><div class="actions"><button class="btn" onclick="loadStory('group')">Load sample group ↗</button>${link('','Start from the homepage','outline')}</div></div><div class="grid"><section class="panel"><div class="eyebrow">01 / GUEST</div><h3>From “let’s go”<br>to your own week.</h3><p class="muted small">Submit an inquiry, add attendees, simulate invitations and complete personal preferences.</p><div class="actions">${link('group','Organizer’s group ↗')}${link('trip-home','Traveler’s home','textlink')}${link('match-home','Solo / small-party path','textlink')}</div></section><section class="panel"><div class="eyebrow">02 / HOST</div><h3>Presence,<br>without the admin.</h3><p class="muted small">Share a ready invitation, review the hosting brief and see compensation information.</p><div class="actions">${link('host-desk','Host home ↗')}${link('apply','Host application','textlink')}</div></section><section class="panel"><div class="eyebrow">03 / COURTSIDE</div><h3>The operation<br>behind the ease.</h3><p class="muted small">Review inquiries, follow up with travelers, send sample proposals and resolve concierge requests.</p><div class="actions">${link('operations','Team workspace ↗')}</div></section></div><section class="panel" style="margin-top:25px"><div class="eyebrow">TRY THE COMPLETE CONCIERGE LOOP</div><h3>One more night in Spain.</h3><div class="steps"><div>1. In a traveler’s view, request an extra night.</div><div>2. Open the request in Courtside’s view and check options.</div><div>3. Prepare a sample offer.</div><div>4. Preview the guest’s view and approve it.</div><div>5. Return to Courtside, check the supplier and confirm.</div><div>6. See the traveler’s arrangements and sample costs update.</div></div><div class="actions">${link('help/new/stay','Start that loop ↗','outline')}<button class="outline" onclick="stageSample()">Skip to a sample confirmed trip</button></div></section>${note('All records are fictional or locally entered sample data. No emails, messages, payments, supplier bookings or real host agreements are created. Data is stored only in this browser and does not synchronize between reviewers. Do not enter private personal information. Photographs come from the supplied Courtside website for concept review.')}<button class="plain danger" onclick="resetDemo()">Reset this browser’s walkthrough data ↻</button>`,'Use the perspective bar to follow the same story across the platform.')}
function resetDemo(){if(!confirm('Reset all Version 2 sample groups, requests and preferences in this browser?'))return;state=fresh();persist();tab='Overview';teamTab='Attention';go('guide');toast('Walkthrough reset.')}
function toggleNav(){const el=$('#mobilenav'),open=el.hidden;el.hidden=!open;$('#navtoggle').setAttribute('aria-expanded',String(open))}
function render(){closeModal();let r=route();if(r==='main'){r='';}if(r.startsWith('request/')){const type=r.split('/')[1];if(!['group','match'].includes(type)){go('start');return}if(type!==state.draft.path){state.draft.path=type;state.draft.step=1;state.draft.weeks=[];persist()}}
const pages={'':home,'trips':()=>shell('Where tennis<br>takes you next.','THE COURTSIDE COLLECTION',`<div class="grid">${tripcard()}${tripcard('mallorca')}${tripcard('charleston')}</div>`,'Start with Spain. Future experiences are ideas until announced.'),'trip':trip,'host':host,'about':about,'apply':apply,'application':application,'application-done':applicationDone,'start':start,'received':receipt,'group':groupPage,'join-group':joinGroup,'attendee-thanks':attendeeThanks,'preferences':preferences,'guest-invitation':preferences,'planning-saved':planningSaved,'proposal':proposal,'payment':payment,'trip-home':tripHome,'arrival':arrival,'help':helpPage,'host-desk':hostDesk,'operations':operations,'invite':invite,'invite-unavailable':unavailableInvite,'waitlist':waitlist,'waitlist-done':waitlistDone,'match-home':matchHome,'guide':guide};
let view;if(r.startsWith('request/'))view=requestPage();else if(r.startsWith('attendee/'))view=attendeePage(r.split('/')[1]);else if(r.startsWith('help/new/'))view=newRequest(r.split('/')[2]);else if(r.startsWith('operations/request/'))view=requestDetail(r.split('/')[2],true);else if(r.startsWith('help/'))view=requestDetail(r.split('/')[1]);else view=(pages[r]||guide)();$('#main').innerHTML=`<div class="route-fade">${view}</div>`;
if(r==='trip'){const eyebrow=[...$('#main').querySelectorAll('.eyebrow')].find(x=>x.textContent==='A WEEK INSIDE KATIE’S SPAIN');if(eyebrow)eyebrow.textContent='TRAVEL WITH KATIE + EVA';}
if(r==='host'){const p=document.createElement('div');p.className='wrap';p.innerHTML='<div class="panel"><div class="eyebrow">A LONG-TERM AMBITION</div><h3>Taking tennis further.</h3><p class="muted small">Katie’s vision includes bringing tennis to more communities and helping local coaches carry it forward. This is a future ambition, not a funded program or a promised allocation from current trips.</p></div>';$('#main .route-fade').append(p)}
const perspective=r.startsWith('operations')?'team':r==='host-desk'||r.startsWith('appl')?'host':r==='guide'?'guide':'guest';document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===perspective));document.title='Courtside — '+({'trip':'The Spanish Offseason','group':'Your group','host-desk':'Host home','operations':'Team workspace','trip-home':'Your week','guide':'Concept 02 walkthrough'}[r]||'Travel together');$('#mobilenav').hidden=true;$('#navtoggle').setAttribute('aria-expanded','false');}
let autosave;document.addEventListener('input',e=>{const form=e.target.closest('[data-draft]');if(form){clearTimeout(autosave);autosave=setTimeout(()=>captureDraft(form),200)}});
window.addEventListener('hashchange',()=>{clearTimeout(autosave);render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});render();

function duringTrip(p){return `<div class="split"><section class="panel"><div class="eyebrow">TODAY · SAMPLE TUESDAY</div><h2>Good morning,<br>${esc(p.name.split(' ')[0])}.</h2><p class="muted small">Your plans, meeting points and help when you need it.</p><div class="schedule"><div class="time">08:45</div><div><h4>${p.role.includes('partner')?'Your morning, your way':'Club transfer'}</h4><p>${p.role.includes('partner')?'Enjoy breakfast and your personal plans.':'Example meeting point: resort reception. Tennis with Katie + Eva follows.'}</p>${badge('Illustrative schedule','warn')}</div></div><div class="schedule"><div class="time">Afternoon</div><div><h4>Space for your own pace.</h4><p>Approved personal arrangements appear in your itinerary.</p></div></div><div class="actions"><button class="btn" onclick="tripPhase='Before travel';tab='My plans';day=2;render()">Open my full itinerary ↗</button>${link('help','Help with my day','outline')}</div></section>${supportPanel()}</div>`}
function afterTrip(p){return `<div class="split"><section class="panel"><div class="eyebrow">UNTIL NEXT TIME</div><h2>A week worth<br>remembering.</h2><p class="muted small">Tell us what felt wonderful and where we could have taken better care of you.</p>${p.feedback?`<div class="offer"><strong>Your sample feedback is saved.</strong><p class="small muted">Thank you. Courtside can use this to improve the next experience.</p></div>`:''}<form onsubmit="saveFeedback(event)"><label>How well did you feel taken care of?${select('careRating',['Choose a response','Very well','Mostly well','We could do better'],p.feedback?.careRating||'Choose a response')}</label><label>Would you travel with this host again?${select('again',['Choose a response','Yes','Maybe','No'],p.feedback?.again||'Choose a response')}</label><label>What should we know?<textarea name="message" required>${esc(p.feedback?.message||'')}</textarea></label><label class="option" style="margin-top:16px"><input type="checkbox" name="future" ${p.feedback?.future?'checked':''}>I’d like to hear about this host’s next trip</label><button class="btn" style="margin-top:20px">Save demo feedback ↗</button></form>${note('Feedback stays in this browser. The future-trip preference does not create a subscription.')}<div class="divider"></div><h3>A few moments from Spain.</h3><div class="largepic">${img('court.jpg','Katie and Eva on a clay court in Spain')}</div><p class="photo-credit">Existing Courtside photograph for concept review. A live trip gallery would use approved shared photographs.</p></section>${supportPanel()}</div>`}
function saveFeedback(e){e.preventDefault();const f=new FormData(e.target);if(f.get('careRating')==='Choose a response'||f.get('again')==='Choose a response')return toast('Choose both responses before saving.');current().feedback={...Object.fromEntries(f),future:f.has('future')};log(current().name+' shared sample post-trip feedback.');persist();render();toast('Feedback saved for the team’s trip review.')}

function supplierDetails(id){const s=state.suppliers.find(s=>s.id===id);modal('Supplier arrangement',`<div class="eyebrow">TEAM · SUPPLIER RECORD</div><h2>${esc(s.title)}</h2><form onsubmit="saveSupplierDetails(event,'${id}')">${field('owner','Responsible person',s.owner||'Trip lead','text',true)}${field('deadline','Hold / follow-up deadline',s.deadline||'','date')}${field('quote','Sample supplier quote · USD',s.quote??'','number')}${field('reference','Sample confirmation reference',s.reference||'','text',false,'Record a reference when confirmed')}<label>Next action / notes<textarea name="notes">${esc(s.notes||'')}</textarea></label>${note('Prototype supplier record. Saving does not contact or book a supplier.')}<button class="btn full">Save sample record ↗</button></form>`)}
function saveSupplierDetails(e,id){e.preventDefault();const f=new FormData(e.target),s=state.suppliers.find(s=>s.id===id);Object.assign(s,Object.fromEntries(f));log('Supplier record updated: '+s.title+'.');persist();closeModal();render();toast('Sample supplier details saved.')}

function completeGroupInquiry(){const d=state.draft;const id='organizer';state.group={id:'CS-2027-001',name:d.name.split(' ')[0]+'’s Spain group',organizerName:d.name,organizerEmail:d.email,weeks:[...d.weeks],chosenDate:d.weeks.find(x=>x!=='Flexible')||'',players:d.players,partners:d.partners,tennis:d.tennis,notes:d.notes,stage:'Inquiry',reviewed:false,paymentMode:'Individual travelers',attendees:[{id,name:d.name,email:d.email,role:'Organizer + player',invited:true,participation:'Interested',complete:false,room:'Help me decide',roommate:'',tennis:d.tennis,interests:[],proposal:'Draft',payment:'Not due'}]};state.active=id;state.requests=[];state.tasks=[];state.matchTraveler=null;tab='Overview';tripPhase='Before travel';log('Private group inquiry received from '+d.name+'.');persist();go('received')}

function loadStory(dest='group'){if(!state.group)return performLoadStory(dest);modal('Load sample story',`<div class="eyebrow">WALKTHROUGH DATA</div><h2>Meet Alex’s group.</h2><p class="muted small">This replaces the group, matching inquiry and concierge requests in this browser with fictional sample records.</p><div class="actions"><button class="btn" onclick="closeModal();performLoadStory('${dest}')">Load sample story ↗</button><button class="outline" onclick="closeModal()">Keep my progress</button></div>`)}
